{"command":"mkdir -p /workspace && cd /workspace && cat > flags.go <<'EOF'
package main

import (
	"encoding/csv"
	"fmt"
	"strconv"
	"strings"
)

type flagKind int

const (
	kindBool flagKind = iota
	kindString
	kindInt
	kindStringSlice
)

// Flag describes a command line option
type Flag struct {
	Name      string
	Shorthand string
	Usage     string
	Kind      flagKind
	DefStr    string // default value string for help
	Changed   bool

	boolVal   *bool
	strVal    *string
	intVal    *int
	sliceVal  *[]string
	noOptDef  string
	hiddenDef bool
}

// FlagSet is an ordered set of flags
type FlagSet struct {
	flags   []*Flag
	byName  map[string]*Flag
	byShort map[string]*Flag
	args    []string
}

func newFlagSet() *FlagSet {
	return &FlagSet{byName: map[string]*Flag{}, byShort: map[string]*Flag{}}
}

func (fs *FlagSet) add(f *Flag) *Flag {
	fs.flags = append(fs.flags, f)
	fs.byName[f.Name] = f
	if f.Shorthand != "" {
		fs.byShort[f.Shorthand] = f
	}
	return f
}

func (fs *FlagSet) BoolVarP(p *bool, name, short string, def bool, usage string) {
	*p = def
	fs.add(&Flag{Name: name, Shorthand: short, Usage: usage, Kind: kindBool, boolVal: p, DefStr: strconv.FormatBool(def), noOptDef: "true"})
}

func (fs *FlagSet) StringVarP(p *string, name, short string, def string, usage string) {
	*p = def
	fs.add(&Flag{Name: name, Shorthand: short, Usage: usage, Kind: kindString, strVal: p, DefStr: def})
}

func (fs *FlagSet) IntVarP(p *int, name, short string, def int, usage string) {
	*p = def
	fs.add(&Flag{Name: name, Shorthand: short, Usage: usage, Kind: kindInt, intVal: p, DefStr: strconv.Itoa(def)})
}

func (fs *FlagSet) StringSliceVarP(p *[]string, name, short string, def []string, usage string) {
	*p = append([]string{}, def...)
	fs.add(&Flag{Name: name, Shorthand: short, Usage: usage, Kind: kindStringSlice, sliceVal: p, DefStr: "[" + strings.Join(def, ",") + "]"})
}

func readAsCSV(val string) ([]string, error) {
	if val == "" {
		return []string{}, nil
	}
	r := csv.NewReader(strings.NewReader(val))
	return r.Read()
}

func (f *Flag) flagNameForErr() string {
	if f.Shorthand != "" {
		return "-" + f.Shorthand + ", --" + f.Name
	}
	return "--" + f.Name
}

func (f *Flag) set(val string) error {
	var err error
	switch f.Kind {
	case kindBool:
		var b bool
		b, err = strconv.ParseBool(val)
		if err == nil {
			*f.boolVal = b
		}
	case kindString:
		*f.strVal = val
	case kindInt:
		var v int64
		v, err = strconv.ParseInt(val, 0, 64)
		if err == nil {
			*f.intVal = int(v)
		}
	case kindStringSlice:
		var v []string
		v, err = readAsCSV(val)
		if err == nil {
			if !f.Changed {
				*f.sliceVal = v
			} else {
				*f.sliceVal = append(*f.sliceVal, v...)
			}
		}
	}
	if err != nil {
		return fmt.Errorf("invalid argument %q for %q flag: %v", val, f.flagNameForErr(), err)
	}
	f.Changed = true
	return nil
}

// Parse parses arguments similarly to spf13/pflag
func (fs *FlagSet) Parse(arguments []string) error {
	fs.args = nil
	for len(arguments) > 0 {
		s := arguments[0]
		arguments = arguments[1:]
		if len(s) == 0 || s[0] != '-' || len(s) == 1 {
			fs.args = append(fs.args, s)
			continue
		}
		var err error
		if s[1] == '-' {
			if len(s) == 2 { // "--"
				fs.args = append(fs.args, arguments...)
				break
			}
			arguments, err = fs.parseLongArg(s, arguments)
		} else {
			arguments, err = fs.parseShortArg(s, arguments)
		}
		if err != nil {
			return err
		}
	}
	return nil
}

func (fs *FlagSet) parseLongArg(s string, args []string) ([]string, error) {
	name := s[2:]
	if len(name) == 0 || name[0] == '-' || name[0] == '=' {
		return args, fmt.Errorf("bad flag syntax: %s", s)
	}
	split := strings.SplitN(name, "=", 2)
	name = split[0]
	flag, ok := fs.byName[name]
	if !ok {
		if name == "help" {
			return args, errHelp
		}
		return args, fmt.Errorf("unknown flag: --%s", name)
	}
	var value string
	if len(split) == 2 {
		value = split[1]
	} else if flag.noOptDef != "" {
		value = flag.noOptDef
	} else if len(args) > 0 {
		value = args[0]
		args = args[1:]
	} else {
		return args, fmt.Errorf("flag needs an argument: %s", s)
	}
	return args, flag.set(value)
}

func (fs *FlagSet) parseShortArg(s string, args []string) ([]string, error) {
	shorthands := s[1:]
	var err error
	for len(shorthands) > 0 {
		shorthands, args, err = fs.parseSingleShortArg(shorthands, args)
		if err != nil {
			return args, err
		}
	}
	return args, nil
}

func (fs *FlagSet) parseSingleShortArg(shorthands string, args []string) (string, []string, error) {
	outShorts := shorthands[1:]
	c := shorthands[0:1]
	flag, ok := fs.byShort[c]
	if !ok {
		if c == "h" {
			return "", args, errHelp
		}
		return outShorts, args, fmt.Errorf("unknown shorthand flag: %q in -%s", c[0], shorthands)
	}
	var value string
	if len(shorthands) > 2 && shorthands[1] == '=' {
		value = shorthands[2:]
		outShorts = ""
	} else if flag.noOptDef != "" {
		value = flag.noOptDef
	} else if len(shorthands) > 1 {
		value = shorthands[1:]
		outShorts = ""
	} else if len(args) > 0 {
		value = args[0]
		args = args[1:]
	} else {
		return outShorts, args, fmt.Errorf("flag needs an argument: %q in -%s", c[0], shorthands)
	}
	return outShorts, args, flag.set(value)
}

var errHelp = fmt.Errorf("pflag: help requested")

// FlagUsages renders the flag list as pflag does
func (fs *FlagSet) FlagUsages() string {
	lines := make([]string, 0, len(fs.flags))
	maxlen := 0
	sorted := fs.sortedFlags()
	for _, f := range sorted {
		line := ""
		if f.Shorthand != "" {
			line = fmt.Sprintf("  -%s, --%s", f.Shorthand, f.Name)
		} else {
			line = fmt.Sprintf("      --%s", f.Name)
		}
		varname, usage := unquoteUsage(f)
		if varname != "" {
			line += " " + varname
		}
		line += "\x00"
		if len(line) > maxlen {
			maxlen = len(line)
		}
		line += usage
		if !f.hiddenDef && !isZeroDefault(f) {
			if f.Kind == kindString {
				line += fmt.Sprintf(" (default %q)", f.DefStr)
			} else {
				line += fmt.Sprintf(" (default %s)", f.DefStr)
			}
		}
		lines = append(lines, line)
	}
	buf := new(strings.Builder)
	for _, line := range lines {
		sidx := strings.Index(line, "\x00")
		spacing := strings.Repeat(" ", maxlen-sidx)
		fmt.Fprintln(buf, line[:sidx], spacing, strings.ReplaceAll(line[sidx+1:], "\n", "\n"+strings.Repeat(" ", maxlen+2)))
	}
	return buf.String()
}

func isZeroDefault(f *Flag) bool {
	switch f.Kind {
	case kindBool:
		return f.DefStr == "false"
	case kindString:
		return f.DefStr == ""
	case kindInt:
		return f.DefStr == "0"
	case kindStringSlice:
		return f.DefStr == "[]"
	}
	return false
}

func unquoteUsage(f *Flag) (string, string) {
	usage := f.Usage
	name := ""
	switch f.Kind {
	case kindBool:
		name = ""
	case kindString:
		name = "string"
	case kindInt:
		name = "int"
	case kindStringSlice:
		name = "strings"
	}
	return name, usage
}

func (fs *FlagSet) sortedFlags() []*Flag {
	res := append([]*Flag{}, fs.flags...)
	// simple insertion sort by name
	for i := 1; i < len(res); i++ {
		for j := i; j > 0 && res[j].Name < res[j-1].Name; j-- {
			res[j], res[j-1] = res[j-1], res[j]
		}
	}
	return res
}
EOF
echo ok"}

