package main

import (
	"time"
)

// Item is a file or directory
type Item interface {
	GetName() string
	GetFlag() rune
	SetFlag(rune)
	IsDir() bool
	GetSize() int64
	GetUsage() int64
	GetMtime() time.Time
	GetItemCount() int
	GetParent() *Dir
	SetParent(*Dir)
	GetPath() string
	GetMultiLinkedInode() uint64
	IsHardLinked() bool
	EncodeJSON(b *jsonWriter, top bool)
}

// File struct
type File struct {
	Name     string
	Flag     rune
	Size     int64
	Usage    int64
	Mtime    time.Time
	Mtimeok  bool
	Ino      uint64
	HardLink bool // nlink > 1
	NotReg   bool // symlink / socket etc for export
	Parent   *Dir
}

func (f *File) GetName() string       { return f.Name }
func (f *File) GetFlag() rune         { return f.Flag }
func (f *File) SetFlag(r rune)        { f.Flag = r }
func (f *File) IsDir() bool           { return false }
func (f *File) GetSize() int64        { return f.Size }
func (f *File) GetUsage() int64       { return f.Usage }
func (f *File) GetMtime() time.Time   { return f.Mtime }
func (f *File) GetItemCount() int     { return 1 }
func (f *File) GetParent() *Dir       { return f.Parent }
func (f *File) SetParent(d *Dir)      { f.Parent = d }
func (f *File) IsHardLinked() bool    { return f.HardLink }
func (f *File) GetMultiLinkedInode() uint64 {
	if f.HardLink {
		return f.Ino
	}
	return 0
}
func (f *File) GetPath() string {
	if f.Parent == nil {
		return f.Name
	}
	return joinPath(f.Parent.GetPath(), f.Name)
}

// Dir struct
type Dir struct {
	File
	BasePath  string
	Files     []Item
	ItemCount int
	ReadErr   bool
}

func (d *Dir) IsDir() bool       { return true }
func (d *Dir) GetItemCount() int { return d.ItemCount }
func (d *Dir) GetPath() string {
	if d.BasePath != "" {
		return joinPath(d.BasePath, d.Name)
	}
	if d.Parent == nil {
		return d.Name
	}
	return joinPath(d.Parent.GetPath(), d.Name)
}

func joinPath(a, b string) string {
	if a == "" {
		return b
	}
	if a[len(a)-1] == '/' {
		return a + b
	}
	return a + "/" + b
}

