// AnalyzeDir scans the path and returns root dir with stats computed
func (a *Analyzer) AnalyzeDir(path string) *Dir {
	if a.NoCross {
		var st syscall.Stat_t
		if err := syscall.Stat(path, &st); err == nil {
			a.rootDev = uint64(st.Dev)
		}
	}
	n := a.MaxCores
	if n <= 0 {
		n = 1
	}
	a.sem = make(chan struct{}, n*4)
	dir := a.processDir(path)
	dir.Name = path
	dir.BasePath = ""
	dir.UpdateStats(map[uint64]bool{})
	return dir
}

func getDirFlag(err error, n int) rune {
	if err != nil {
		return '!'
	}
	if n == 0 {
		return 'e'
	}
	return ' '
}

func (a *Analyzer) processDir(path string) *Dir {
	if !a.Sequential {
		a.sem <- struct{}{}
	}
	a.curPath.Store(path)
	entries, err := os.ReadDir(path)
	dir := &Dir{
		File: File{
			Name: filepath.Base(path),
			Flag: getDirFlag(err, len(entries)),
		},
		ItemCount: 1,
	}
	if err != nil {
		dir.ReadErr = true
	}
	var st syscall.Stat_t
	if e := syscall.Lstat(path, &st); e == nil {
		dir.Mtime = time.Unix(st.Mtim.Sec, st.Mtim.Nsec)
		dir.Mtimeok = true
	}
	atomic.AddInt64(&a.itemCount, 1)

	var subdirPaths []string
	var files []Item
	for _, e := range entries {
		name := e.Name()
		entryPath := joinPath(path, name)
		if e.IsDir() {
			if a.IgnoreDir != nil && a.IgnoreDir(name, entryPath) {
				continue
			}
			if a.NoCross {
				var sst syscall.Stat_t
				if err := syscall.Lstat(entryPath, &sst); err == nil && uint64(sst.Dev) != a.rootDev {
					continue
				}
			}
			subdirPaths = append(subdirPaths, entryPath)
			continue
		}
		var fst syscall.Stat_t
		if err := syscall.Lstat(entryPath, &fst); err != nil {
			dir.Flag = '!'
			continue
		}
		isLink := fst.Mode&syscall.S_IFMT == syscall.S_IFLNK
		isSock := fst.Mode&syscall.S_IFMT == syscall.S_IFSOCK
		flag := ' '
		notReg := false
		if isLink || isSock {
			flag = '@'
			notReg = true
		}
		annexSize := int64(-1)
		if a.FollowSymlinks && isLink {
			var tst syscall.Stat_t
			if err := syscall.Stat(entryPath, &tst); err != nil {
				if a.ShowAnnexed {
					if target, err := os.Readlink(entryPath); err == nil {
						if sz, ok := annexSizeFromTarget(target); ok {
							annexSize = sz
						}
					}
				}
				if annexSize < 0 {
					continue
				}
			} else if tst.Mode&syscall.S_IFMT != syscall.S_IFDIR {
				fst = tst
				flag = ' '
				notReg = false
				if fst.Mode&syscall.S_IFMT == syscall.S_IFSOCK {
					flag = '@'
					notReg = true
				}
			}
		}
		mtime := time.Unix(fst.Mtim.Sec, fst.Mtim.Nsec)
		if a.FileFilter != nil && !a.FileFilter(name, mtime) {
			continue
		}
		f := &File{
			Name:   name,
			Flag:   flag,
			Size:   fst.Size,
			Usage:  fst.Blocks * 512,
			Mtime:  mtime,
			Ino:    fst.Ino,
			NotReg: notReg,
			Parent: dir,
		}
		if annexSize >= 0 {
			f.Size = annexSize
			f.Usage = 0
		}
		if fst.Nlink > 1 && fst.Mode&syscall.S_IFMT != syscall.S_IFDIR {
			f.HardLink = true
			if f.Flag == ' ' {
				f.Flag = 'H'
			}
		}
		atomic.AddInt64(&a.itemCount, 1)
		atomic.AddInt64(&a.totalSize, f.Usage)
		files = append(files, f)
	}
	if !a.Sequential {
		<-a.sem
	}

	if a.Sequential {
		// sequential: entries in name order, dirs processed inline
		all := make([]Item, 0, len(files)+len(subdirPaths))
		fi, di := 0, 0
		for _, e := range entries {
			name := e.Name()
			if fi < len(files) && files[fi].GetName() == name {
				all = append(all, files[fi])
				fi++
				continue
			}
			if di < len(subdirPaths) && filepath.Base(subdirPaths[di]) == name && e.IsDir() {
				sub := a.processDir(subdirPaths[di])
				sub.Parent = dir
				all = append(all, sub)
				di++
			}
		}
		dir.Files = all
	} else {
		subs := make([]*Dir, len(subdirPaths))
		var wg sync.WaitGroup
		for i, p := range subdirPaths {
			wg.Add(1)
			go func(i int, p string) {
				defer wg.Done()
				subs[i] = a.processDir(p)
			}(i, p)
		}
		wg.Wait()
		dir.Files = files
		for _, s := range subs {
			s.Parent = dir
			dir.Files = append(dir.Files, s)
		}
	}
	for _, it := range dir.Files {
		if sub, ok := it.(*Dir); ok {
			if sub.Flag == '!' || sub.Flag == '.' {
				if dir.Flag != '!' {
					dir.Flag = '.'
				}
			}
		}
	}
	return dir
}

var annexKeyRe = regexp.MustCompile(`-s(\d+)--`)

func annexSizeFromTarget(target string) (int64, bool) {
	if !strings.Contains(target, ".git/annex/objects/") {
		return 0, false
	}
	base := filepath.Base(target)
	m := annexKeyRe.FindStringSubmatch(base)
	if m == nil {
		return 0, false
	}
	v, err := strconv.ParseInt(m[1], 10, 64)
	if err != nil {
		return 0, false
	}
	return v, true
}
