// Ignorer decides which directories to skip
type Ignorer struct {
	paths      map[string]bool
	prefixRe   *regexp.Regexp
	suffixRe   *regexp.Regexp
	noHidden   bool
	hasPattern bool
}

func newIgnorer() *Ignorer {
	return &Ignorer{paths: map[string]bool{}}
}

// SetIgnoreDirPaths sets paths to ignore
func (ig *Ignorer) SetIgnoreDirPaths(paths []string) {
	ig.paths = map[string]bool{}
	for _, p := range paths {
		if !filepath.IsAbs(p) {
			if abs, err := filepath.Abs(p); err == nil {
				p = abs
			}
		}
		ig.paths[p] = true
	}
}

// SetIgnoreDirPatterns compiles patterns
func (ig *Ignorer) SetIgnoreDirPatterns(patterns []string) error {
	if len(patterns) == 0 {
		ig.hasPattern = false
		ig.prefixRe = nil
		ig.suffixRe = nil
		return nil
	}
	grouped := make([]string, len(patterns))
	for i, p := range patterns {
		if _, err := regexp.Compile(p); err != nil {
			return err
		}
		grouped[i] = "(" + p + ")"
	}
	re1, err := regexp.Compile("^" + strings.Join(grouped, "|"))
	if err != nil {
		return err
	}
	var sb strings.Builder
	for i, p := range patterns {
		if i > 0 {
			sb.WriteString("|")
		}
		if filepath.IsAbs(p) {
			c := filepath.Clean(p)
			sb.WriteString(strings.TrimPrefix(c, "/"))
		} else {
			if i == 0 {
				sb.WriteString("^")
			}
			sb.WriteString(p)
		}
	}
	sb.WriteString("$")
	re2, err := regexp.Compile(sb.String())
	if err != nil {
		// fall back to only the prefix matcher
		re2 = nil
	}
	ig.prefixRe = re1
	ig.suffixRe = re2
	ig.hasPattern = true
	return nil
}

// SetIgnoreFromFile reads patterns from file
func (ig *Ignorer) SetIgnoreFromFile(file string) error {
	f, err := os.Open(file)
	if err != nil {
		return err
	}
	defer f.Close()
	var lines []string
	sc := bufio.NewScanner(f)
	for sc.Scan() {
		lines = append(lines, sc.Text())
	}
	return ig.SetIgnoreDirPatterns(lines)
}

// ShouldDirBeIgnored decides about a directory
func (ig *Ignorer) ShouldDirBeIgnored(name, path string) bool {
	if ig.noHidden && strings.HasPrefix(name, ".") {
		return true
	}
	if ig.paths[path] {
		return true
	}
	if ig.hasPattern {
		if ig.prefixRe != nil && ig.prefixRe.MatchString(path) {
			return true
		}
		if ig.suffixRe != nil && ig.suffixRe.MatchString(path) {
			return true
		}
	}
	return false
}
