package main

import (
	"fmt"
	"sort"
)

const (
	_          = iota
	KB float64 = 1 << (10 * iota)
	MB
	GB
	TB
	PB
	EB
)

const (
	K  float64 = 1e3
	M  float64 = 1e6
	G  float64 = 1e9
	T  float64 = 1e12
	P  float64 = 1e15
	E  float64 = 1e18
)

// formatSizeParts returns number and unit strings
func formatSizeParts(size int64, si bool) (string, string) {
	fsize := float64(size)
	if si {
		switch {
		case fsize >= E:
			return fmt.Sprintf("%.1f", fsize/E), "EB"
		case fsize >= P:
			return fmt.Sprintf("%.1f", fsize/P), "PB"
		case fsize >= T:
			return fmt.Sprintf("%.1f", fsize/T), "TB"
		case fsize >= G:
			return fmt.Sprintf("%.1f", fsize/G), "GB"
		case fsize >= M:
			return fmt.Sprintf("%.1f", fsize/M), "MB"
		case fsize >= K:
			return fmt.Sprintf("%.1f", fsize/K), "kB"
		default:
			return fmt.Sprintf("%d", size), "B"
		}
	}
	switch {
	case fsize >= EB:
		return fmt.Sprintf("%.1f", fsize/EB), "EiB"
	case fsize >= PB:
		return fmt.Sprintf("%.1f", fsize/PB), "PiB"
	case fsize >= TB:
		return fmt.Sprintf("%.1f", fsize/TB), "TiB"
	case fsize >= GB:
		return fmt.Sprintf("%.1f", fsize/GB), "GiB"
	case fsize >= MB:
		return fmt.Sprintf("%.1f", fsize/MB), "MiB"
	case fsize >= KB:
		return fmt.Sprintf("%.1f", fsize/KB), "KiB"
	default:
		return fmt.Sprintf("%d", size), "B"
	}
}

func isDigit(c byte) bool { return c >= '0' && c <= '9' }

// naturalLess compares strings with numeric awareness
func naturalLess(a, b string) bool {
	i, j := 0, 0
	for i < len(a) && j < len(b) {
		ca, cb := a[i], b[j]
		if isDigit(ca) && isDigit(cb) {
			var na, nb int64
			for i < len(a) && isDigit(a[i]) {
				na = na*10 + int64(a[i]-'0')
				i++
			}
			for j < len(b) && isDigit(b[j]) {
				nb = nb*10 + int64(b[j]-'0')
				j++
			}
			if na != nb {
				return na < nb
			}
			continue
		}
		if ca != cb {
			return ca < cb
		}
		i++
		j++
	}
	return a < b
}

// sortByUsageDesc sorts items by usage desc, then by name desc (natural)
func sortByUsageDesc(items []Item) {
	sort.SliceStable(items, func(i, j int) bool {
		ui, uj := items[i].GetUsage(), items[j].GetUsage()
		if ui != uj {
			return ui > uj
		}
		return naturalLess(items[j].GetName(), items[i].GetName())
	})
}
