package main

import (
	"container/heap"
	"fmt"
	"io"
	"path/filepath"
	"sort"
	"strings"
	"sync"
	"time"
)

// StdoutUI prints results to stdout
type StdoutUI struct {
	out          io.Writer
	useColors    bool
	showProgress bool
	showApparent bool
	summarize    bool
	noPrefix     bool
	si           bool
	kib          bool
	reverseSort  bool
	top          int
	depth        int
}

func colorYellow(s string) string { return "\x1b[33;1m" + s + "\x1b[0;22m" }
func colorBlue(s string) string   { return "\x1b[34;1m" + s + "\x1b[0;22m" }
func colorRed(s string) string    { return "\x1b[31;1m" + s + "\x1b[0;22m" }

func (ui *StdoutUI) num(s string) string {
	if ui.useColors {
		return colorYellow(s)
	}
	return s
}

func (ui *StdoutUI) formatSize(size int64) string {
	if ui.noPrefix {
		return ui.num(fmt.Sprintf("%d", size))
	}
	if ui.kib {
		if ui.si {
			return ui.num(fmt.Sprintf("%.1f", float64(size)/K)) + " kB"
		}
		return ui.num(fmt.Sprintf("%.1f", float64(size)/KB)) + " KiB"
	}
	n, u := formatSizeParts(size, ui.si)
	return ui.num(n) + " " + u
}

func (ui *StdoutUI) sizeWidth() int {
	if ui.useColors {
		return 20
	}
	return 9
}

func (ui *StdoutUI) itemSize(it Item) int64 {
	if ui.showApparent {
		return it.GetSize()
	}
	return it.GetUsage()
}

// ShowDir prints the analysis result
func (ui *StdoutUI) ShowDir(dir *Dir) {
	if ui.top > 0 {
		ui.printTop(dir)
		return
	}
	if ui.depth > 0 {
		ui.printDepth(dir, 0, dir.Name)
		return
	}
	if ui.summarize {
		fmt.Fprintf(ui.out, "%*s %s\n", ui.sizeWidth(), ui.formatSize(ui.itemSize(dir)), filepath.Base(dir.Name))
		return
	}
	files := append([]Item{}, dir.Files...)
	sortByUsageDesc(files)
	if ui.reverseSort {
		reverseItems(files)
	}
	for _, f := range files {
		name := f.GetName()
		if f.IsDir() {
			name = "/" + name
			if ui.useColors {
				name = colorBlue(name)
			}
		}
		fmt.Fprintf(ui.out, "%c %*s %s\n", f.GetFlag(), ui.sizeWidth(), ui.formatSize(ui.itemSize(f)), name)
	}
}

func reverseItems(items []Item) {
	for i, j := 0, len(items)-1; i < j; i, j = i+1, j-1 {
		items[i], items[j] = items[j], items[i]
	}
}

func (ui *StdoutUI) printDepth(item Item, level int, path string) {
	name := path
	if item.IsDir() && ui.useColors {
		name = colorBlue(name)
	}
	fmt.Fprintf(ui.out, "%*s %s\n", ui.sizeWidth(), ui.formatSize(ui.itemSize(item)), name)
	d, ok := item.(*Dir)
	if !ok || level >= ui.depth {
		return
	}
	files := append([]Item{}, d.Files...)
	sortByUsageDesc(files)
	if ui.reverseSort {
		reverseItems(files)
	}
	for _, f := range files {
		ui.printDepth(f, level+1, joinPath(path, f.GetName()))
	}
}

type topEntry struct {
	item Item
	path string
}

type topHeap []topEntry

func (h topHeap) Len() int            { return len(h) }
func (h topHeap) Less(i, j int) bool  { return h[i].item.GetSize() < h[j].item.GetSize() }
func (h topHeap) Swap(i, j int)       { h[i], h[j] = h[j], h[i] }
func (h *topHeap) Push(x interface{}) { *h = append(*h, x.(topEntry)) }
func (h *topHeap) Pop() interface{} {
	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[:n-1]
	return x
}

func (ui *StdoutUI) printTop(dir *Dir) {
	h := &topHeap{}
	var walk func(d *Dir, path string)
	walk = func(d *Dir, path string) {
		files := append([]Item{}, d.Files...)
		sortByUsageDesc(files)
		for _, f := range files {
			p := joinPath(path, f.GetName())
			if sub, ok := f.(*Dir); ok {
				walk(sub, p)
				continue
			}
			if h.Len() < ui.top {
				heap.Push(h, topEntry{f, p})
			} else if f.GetSize() > (*h)[0].item.GetSize() {
				(*h)[0] = topEntry{f, p}
				heap.Fix(h, 0)
			}
		}
	}
	walk(dir, dir.Name)
	res := []topEntry(*h)
	sort.SliceStable(res, func(i, j int) bool { return res[i].item.GetSize() > res[j].item.GetSize() })
	for _, e := range res {
		fmt.Fprintf(ui.out, "%*s %s\n", ui.sizeWidth(), ui.formatSize(ui.itemSize(e.item)), e.path)
	}
}

var progressRunes = []rune("⠇⠏⠋⠙⠹⠸⠼⠴⠦⠧")

// progressPrinter shows progress until done is closed
func (ui *StdoutUI) startProgress(text func() string) (stop func()) {
	if !ui.showProgress {
		return func() {}
	}
	emptyRow := "\r" + strings.Repeat(" ", 100)
	done := make(chan struct{})
	var wg sync.WaitGroup
	wg.Add(1)
	go func() {
		defer wg.Done()
		i := 0
		fmt.Fprint(ui.out, emptyRow)
		for {
			fmt.Fprint(ui.out, emptyRow)
			select {
			case <-done:
				fmt.Fprint(ui.out, "\r")
				return
			default:
			}
			fmt.Fprintf(ui.out, "\r %s ", string(progressRunes[i]))
			fmt.Fprint(ui.out, text())
			select {
			case <-done:
				fmt.Fprint(ui.out, emptyRow)
				fmt.Fprint(ui.out, "\r")
				return
			case <-time.After(100 * time.Millisecond):
			}
			i = (i + 1) % 10
		}
	}()
	return func() {
		close(done)
		wg.Wait()
	}
}
EOF
