				f.Flag = '@'
				f.NotReg = true
			}
			if v, ok := it["ino"].(float64); ok {
				f.Ino = uint64(v)
				f.HardLink = f.Ino != 0
				f.Flag = 'H'
			}
			if _, ok := it["hlnkc"].(bool); ok {
				f.Flag = 'H'
			}
			dir.Files = append(dir.Files, f)
		case []interface{}:
			sub, err := importDir(it)
			if err != nil {
				return nil, err
			}
			sub.Parent = dir
			dir.Files = append(dir.Files, sub)
		}
	}
	return dir, nil
}

func handleImportPanic() {
	if r := recover(); r != nil {
		if p, ok := r.(*ImportPanic); ok {
			fmt.Fprintf(os.Stderr, "panic: %s\n\ngoroutine 7 [running]:\n", p.msg)
			os.Exit(2)
		}
		panic(r)
	}
}
