package main

import (
	"fmt"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"
	"time"
)

var durationRe = regexp.MustCompile(`^(\d+(y|mo|w|d|h|m|s))+$`)
var durationPartRe = regexp.MustCompile(`(\d+)(y|mo|w|d|h|m|s)`)

func parseAgeDuration(s string) (time.Duration, error) {
	v := strings.ToLower(strings.TrimSpace(s))
	if !durationRe.MatchString(v) {
		return 0, fmt.Errorf("invalid duration format %q. Use combinations like 7d, 2h30m, 1y2mo", s)
	}
	var total time.Duration
	for _, m := range durationPartRe.FindAllStringSubmatch(v, -1) {
		n, err := strconv.ParseInt(m[1], 10, 64)
		if err != nil {
			return 0, fmt.Errorf("invalid duration format %q. Use combinations like 7d, 2h30m, 1y2mo", s)
		}
		var unit time.Duration
		switch m[2] {
		case "y":
			unit = 365 * 24 * time.Hour
		case "mo":
			unit = 30 * 24 * time.Hour
		case "w":
			unit = 7 * 24 * time.Hour
		case "d":
			unit = 24 * time.Hour
		case "h":
			unit = time.Hour
		case "m":
			unit = time.Minute
		case "s":
			unit = time.Second
		}
		total += time.Duration(n) * unit
	}
	return total, nil
}

type timeBound struct {
	set      bool
	dateOnly bool
	t        time.Time
}

func parseWhen(s string) (timeBound, error) {
	v := strings.TrimSpace(s)
	if t, err := time.ParseInLocation("2006-01-02", v, time.Local); err == nil {
		return timeBound{set: true, dateOnly: true, t: t}, nil
	}
	if t, err := time.Parse(time.RFC3339, v); err == nil {
		return timeBound{set: true, t: t}, nil
	}
	return timeBound{}, fmt.Errorf("invalid time value %q. Use RFC3339 timestamp or YYYY-MM-DD", s)
}

// TimeFilter filters files by mtime
type TimeFilter struct {
	active   bool
	maxAgeOK bool
	minAgeOK bool
	maxAge   time.Time // mtime must be >= this
	minAge   time.Time // mtime must be <= this
	since    timeBound
	until    timeBound
}

func newTimeFilter(maxAge, minAge, since, until string) (*TimeFilter, error) {
	tf := &TimeFilter{}
	now := time.Now()
	if strings.TrimSpace(maxAge) != "" {
		d, err := parseAgeDuration(maxAge)
		if err != nil {
			return nil, fmt.Errorf("invalid --max-age value: %v", err)
		}
		tf.maxAgeOK = true
		tf.maxAge = now.Add(-d)
		tf.active = true
	}
	if strings.TrimSpace(minAge) != "" {
		d, err := parseAgeDuration(minAge)
		if err != nil {
			return nil, fmt.Errorf("invalid --min-age value: %v", err)
		}
		tf.minAgeOK = true
		tf.minAge = now.Add(-d)
		tf.active = true
	}
	if strings.TrimSpace(since) != "" {
		b, err := parseWhen(since)
		if err != nil {
			return nil, fmt.Errorf("invalid --since value: %v", err)
		}
		tf.since = b
		tf.active = true
	}
	if strings.TrimSpace(until) != "" {
		b, err := parseWhen(until)
		if err != nil {
			return nil, fmt.Errorf("invalid --until value: %v", err)
		}
		tf.until = b
		tf.active = true
	}
	return tf, nil
}

func dateOf(t time.Time) time.Time {
	y, m, d := t.In(time.Local).Date()
	return time.Date(y, m, d, 0, 0, 0, 0, time.Local)
}

// Include returns true if file with given mtime passes
func (tf *TimeFilter) Include(mtime time.Time) bool {
	if !tf.active {
		return true
	}
	if tf.maxAgeOK && mtime.Before(tf.maxAge) {
		return false
	}
	if tf.minAgeOK && mtime.After(tf.minAge) {
		return false
	}
	if tf.since.set {
		if tf.since.dateOnly {
			if dateOf(mtime).Before(tf.since.t) {
				return false
			}
		} else if mtime.Before(tf.since.t) {
			return false
		}
	}
	if tf.until.set {
		if tf.until.dateOnly {
			if dateOf(mtime).After(tf.until.t) {
				return false
			}
		} else if mtime.After(tf.until.t) {
			return false
		}
	}
	return true
}

// TypeFilter filters files by extension
type TypeFilter struct {
	include map[string]bool
	exclude map[string]bool
}

func normalizeExt(t string) string {
	t = strings.ToLower(strings.TrimSpace(t))
	if t == "" {
		return ""
	}
	if !strings.HasPrefix(t, ".") {
		t = "." + t
	}
	return t
}

func newTypeFilter(include, exclude []string) *TypeFilter {
	tf := &TypeFilter{}
	for _, t := range include {
		if n := normalizeExt(t); n != "" {
			if tf.include == nil {
				tf.include = map[string]bool{}
			}
			tf.include[n] = true
		}
	}
	for _, t := range exclude {
		if n := normalizeExt(t); n != "" {
			if tf.exclude == nil {
				tf.exclude = map[string]bool{}
			}
			tf.exclude[n] = true
		}
	}
	return tf
}

