package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
	"syscall"
)

// Device is a mounted filesystem
type Device struct {
	Name       string
	MountPoint string
	Fstype     string
	Size       int64
	Free       int64
}

func unescapeMount(s string) string {
	if !strings.Contains(s, "\\") {
		return s
	}
	var sb strings.Builder
	for i := 0; i < len(s); i++ {
		if s[i] == '\\' && i+3 < len(s) {
			if v, err := strconv.ParseUint(s[i+1:i+4], 8, 8); err == nil {
				sb.WriteByte(byte(v))
				i += 3
				continue
			}
		}
		sb.WriteByte(s[i])
	}
	return sb.String()
}

func getMounts() ([]*Device, error) {
	f, err := os.Open("/proc/mounts")
	if err != nil {
		return nil, err
	}
	defer f.Close()
	var res []*Device
	sc := bufio.NewScanner(f)
	for sc.Scan() {
		parts := strings.Fields(sc.Text())
		if len(parts) < 3 {
			continue
		}
		res = append(res, &Device{Name: parts[0], MountPoint: unescapeMount(parts[1]), Fstype: parts[2]})
	}
	return res, nil
}

func getDevicesInfo() ([]*Device, error) {
	mounts, err := getMounts()
	if err != nil {
		return nil, err
	}
	var res []*Device
	for _, m := range mounts {
		if strings.Contains(m.MountPoint, "/snap/") {
			continue
		}
		if strings.HasPrefix(m.Name, "/dev") || m.Fstype == "zfs" || m.Fstype == "nfs" || m.Fstype == "nfs4" {
			var st syscall.Statfs_t
			if err := syscall.Statfs(m.MountPoint, &st); err != nil {
				return nil, err
			}
			m.Size = int64(st.Bsize) * int64(st.Blocks)
			m.Free = int64(st.Bsize) * int64(st.Bavail)
			res = append(res, m)
		}
	}
	return res, nil
}

func usedPercent(d *Device) float64 {
	if d.Size == 0 {
		return 0
	}
	return float64(d.Size-d.Free) / float64(d.Size) * 100
}

// ListDevices prints devices table
func (ui *StdoutUI) ListDevices(devices []*Device) {
	maxName := len("Device")
	for _, d := range devices {
		if len(d.Name) > maxName {
			maxName = len(d.Name)
		}
	}
	sizeLen, pctLen := 9, 5
	if ui.useColors {
		sizeLen, pctLen = 20, 16
	}
	header := fmt.Sprintf("%%%ds %%%ds %%%ds %%%ds %%%ds %%s\n", maxName, 9, 9, 9, 5)
	line := fmt.Sprintf("%%%ds %%%ds %%%ds %%%ds %%%ds %%s\n", maxName, sizeLen, sizeLen, sizeLen, pctLen)
	fmt.Fprintf(ui.out, header, "Device", "Size", "Used", "Free", "Used%", "Mount point")
	for _, d := range devices {
		pct := fmt.Sprintf("%.0f%%", usedPercent(d))
		if ui.useColors {
			pct = colorRed(pct)
		}
		fmt.Fprintf(ui.out, line, d.Name, ui.formatSize(d.Size), ui.formatSize(d.Size-d.Free), ui.formatSize(d.Free), pct, d.MountPoint)
	}
}
EOF
echo ok"}

