{"command":"cd /workspace && cat > yaml.go <<'EOF'
package main

import (
	"errors"
	"strconv"
	"strings"
)

// minimal YAML subset parser producing map[string]interface{}, []interface{}, scalars (as yamlScalar)

type yamlScalar struct {
	val    string
	quoted bool
}

type yline struct {
	indent int
	text   string
}

func stripComment(s string) string {
	inS, inD := false, false
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case c == '\'' && !inD:
			inS = !inS
		case c == '"' && !inS:
			inD = !inD
		case c == '#' && !inS && !inD:
			if i == 0 || s[i-1] == ' ' || s[i-1] == '\t' {
				return s[:i]
			}
		}
	}
	return s
}

func parseYAML(data string) (map[string]interface{}, error) {
	var lines []yline
	for _, raw := range strings.Split(strings.ReplaceAll(data, "\r\n", "\n"), "\n") {
		if strings.Contains(raw, "\t") && strings.TrimLeft(raw, " ") != "" && strings.HasPrefix(strings.TrimLeft(raw, " "), "\t") {
			return nil, errors.New("found tab")
		}
		t := strings.TrimRight(stripComment(raw), " \t")
		if strings.TrimSpace(t) == "" {
			continue
		}
		if strings.TrimSpace(t) == "---" {
			continue
		}
		ind := len(t) - len(strings.TrimLeft(t, " "))
		lines = append(lines, yline{ind, strings.TrimLeft(t, " ")})
	}
	if len(lines) == 0 {
		return map[string]interface{}{}, nil
	}
	p := &yparser{lines: lines}
	v, err := p.parseBlock(lines[0].indent)
	if err != nil {
		return nil, err
	}
	if p.pos < len(p.lines) {
		return nil, errors.New("unexpected content")
	}
	m, ok := v.(map[string]interface{})
	if !ok {
		return nil, errors.New("not a map")
	}
	return m, nil
}

type yparser struct {
	lines []yline
	pos   int
}

func (p *yparser) parseBlock(indent int) (interface{}, error) {
	if p.pos >= len(p.lines) {
		return nil, nil
	}
	if strings.HasPrefix(p.lines[p.pos].text, "- ") || p.lines[p.pos].text == "-" {
		return p.parseList(indent)
	}
	return p.parseMap(indent)
}

func splitKey(text string) (string, string, bool) {
	// find ": " or trailing ":" outside quotes
	inS, inD := false, false
	for i := 0; i < len(text); i++ {
		c := text[i]
		switch {
		case c == '\'' && !inD:
			inS = !inS
		case c == '"' && !inS:
			inD = !inD
		case c == ':' && !inS && !inD:
			if i == len(text)-1 || text[i+1] == ' ' {
				key := strings.TrimSpace(text[:i])
				if len(key) >= 2 && (key[0] == '"' || key[0] == '\'') {
					key = key[1 : len(key)-1]
				}
				return key, strings.TrimSpace(text[i+1:]), true
			}
		}
	}
	return "", "", false
}

func (p *yparser) parseMap(indent int) (interface{}, error) {
	m := map[string]interface{}{}
	for p.pos < len(p.lines) {
		l := p.lines[p.pos]
		if l.indent < indent {
			break
		}
		if l.indent > indent {
			return nil, errors.New("bad indentation")
		}
		key, rest, ok := splitKey(l.text)
		if !ok {
			return nil, errors.New("expected key")
		}
		p.pos++
		if rest == "" {
			if p.pos < len(p.lines) && (p.lines[p.pos].indent > indent ||
				(p.lines[p.pos].indent == indent && strings.HasPrefix(p.lines[p.pos].text, "- "))) {
				v, err := p.parseBlock(p.lines[p.pos].indent)
				if err != nil {
					return nil, err
				}
				m[key] = v
			} else {
				m[key] = nil
			}
			continue
		}
		v, err := parseInline(rest)
		if err != nil {
			return nil, err
		}
		m[key] = v
	}
	return m, nil
}

func (p *yparser) parseList(indent int) (interface{}, error) {
	var list []interface{}
	for p.pos < len(p.lines) {
		l := p.lines[p.pos]
		if l.indent < indent || !(strings.HasPrefix(l.text, "- ") || l.text == "-") {
			break
		}
		if l.indent > indent {
			return nil, errors.New("bad indentation")
		}
		rest := strings.TrimSpace(strings.TrimPrefix(l.text, "-"))
		p.pos++
		if rest == "" {
			if p.pos < len(p.lines) && p.lines[p.pos].indent > indent {
				v, err := p.parseBlock(p.lines[p.pos].indent)
				if err != nil {
					return nil, err
				}
				list = append(list, v)
			} else {
				list = append(list, nil)
			}
			continue
		}
		if _, _, ok := splitKey(rest); ok && !strings.HasPrefix(rest, "[") && !strings.HasPrefix(rest, "{") && !strings.HasPrefix(rest, "\"") && !strings.HasPrefix(rest, "'") {
			// map inside list
			sub := []yline{{indent + 2, rest}}
			for p.pos < len(p.lines) && p.lines[p.pos].indent > indent {
				sub = append(sub, p.lines[p.pos])
				p.pos++
			}
			sp := &yparser{lines: sub}
			v, err := sp.parseMap(indent + 2)
			if err != nil {
				return nil, err
			}
			list = append(list, v)
			continue
		}
		v, err := parseInline(rest)
		if err != nil {
			return nil, err
		}
		list = append(list, v)
	}
	return list, nil
}

func parseInline(s string) (interface{}, error) {
	s = strings.TrimSpace(s)
	if strings.HasPrefix(s, "[") {
		if !strings.HasSuffix(s, "]") {
			return nil, errors.New("unterminated flow sequence")
		}
		inner := strings.TrimSpace(s[1 : len(s)-1])
		var list []interface{}
		if inner == "" {
			return []interface{}{}, nil
		}
		for _, part := range splitFlow(inner) {
			v, err := parseInline(part)
			if err != nil {
				return nil, err
			}
			list = append(list, v)
		}
		return list, nil
	}
	if strings.HasPrefix(s, "{") {
		if !strings.HasSuffix(s, "}") {
			return nil, errors.New("unterminated flow mapping")
		}
		inner := strings.TrimSpace(s[1 : len(s)-1])
		m := map[string]interface{}{}
		if inner == "" {
			return m, nil
		}
		for _, part := range splitFlow(inner) {
			k, v, ok := splitKey(part)
			if !ok {
				return nil, errors.New("bad flow mapping")
			}
			pv, err := parseInline(v)
			if err != nil {
				return nil, err
			}
			m[k] = pv
		}
		return m, nil
	}
	if strings.HasPrefix(s, "\"") {
		if len(s) < 2 || !strings.HasSuffix(s, "\"") {
			return nil, errors.New("unterminated string")
		}
		v, err := strconv.Unquote(s)
		if err != nil {
			v = s[1 : len(s)-1]
		}
		return yamlScalar{val: v, quoted: true}, nil
	}
	if strings.HasPrefix(s, "'") {
		if len(s) < 2 || !strings.HasSuffix(s, "'") {
			return nil, errors.New("unterminated string")
		}
		return yamlScalar{val: strings.ReplaceAll(s[1:len(s)-1], "''", "'"), quoted: true}, nil
	}
	if strings.HasPrefix(s, "&") || strings.HasPrefix(s, "*") || strings.HasPrefix(s, "!") || strings.HasPrefix(s, "%") || strings.HasPrefix(s, "@") || strings.HasPrefix(s, "`") {
		return nil, errors.New("unsupported")
	}
	return yamlScalar{val: s}, nil
}

func splitFlow(s string) []string {
	var parts []string
	depth := 0
	inS, inD := false, false
	start := 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case c == '\'' && !inD:
			inS = !inS
		case c == '"' && !inS:
			inD = !inD
		case (c == '[' || c == '{') && !inS && !inD:
			depth++
		case (c == ']' || c == '}') && !inS && !inD:
			depth--
		case c == ',' && depth == 0 && !inS && !inD:
			parts = append(parts, strings.TrimSpace(s[start:i]))
			start = i + 1
		}
	}
	last := strings.TrimSpace(s[start:])
	if last != "" {
		parts = append(parts, last)
	}
	return parts
}

func yamlBool(v interface{}) (bool, bool) {
	s, ok := v.(yamlScalar)
	if !ok || s.quoted {
		return false, false
	}
	switch s.val {
	case "y", "Y", "yes", "Yes", "YES", "true", "True", "TRUE", "on", "On", "ON":
		return true, true
	case "n", "N", "no", "No", "NO", "false", "False", "FALSE", "off", "Off", "OFF":
		return false, true
	}
	return false, false
}

func yamlInt(v interface{}) (int, bool) {
	s, ok := v.(yamlScalar)
	if !ok || s.quoted {
		return 0, false
	}
	t := strings.ReplaceAll(s.val, "_", "")
	if n, err := strconv.ParseInt(t, 0, 64); err == nil {
		return int(n), true
	}
	if strings.HasPrefix(t, "0o") {
		if n, err := strconv.ParseInt(t[2:], 8, 64); err == nil {
			return int(n), true
		}
	}
	if f, err := strconv.ParseFloat(t, 64); err == nil && f == float64(int64(f)) {
		return int(f), true
	}
	return 0, false
}

func yamlString(v interface{}) (string, bool) {
	if v == nil {
		return "", true
	}
	s, ok := v.(yamlScalar)
	if !ok {
		return "", false
	}
	if !s.quoted && (s.val == "~" || s.val == "null" || s.val == "Null" || s.val == "NULL") {
		return "", true
	}
	return s.val, true
