func rootHelp(fs *FlagSet) string {
	return "Pretty fast disk usage analyzer written in Go.\n\n" +
		"Gdu is intended primarily for SSD disks where it can fully utilize parallel processing.\n" +
		"However HDDs work as well, but the performance gain is not so huge.\n\n" +
		"Usage:\n  gdu [directory_to_scan] [flags]\n\nFlags:\n" + fs.FlagUsages()
}

func isTerminal(fd uintptr) bool {
	var termios syscall.Termios
	_, _, err := syscall.Syscall(syscall.SYS_IOCTL, fd, syscall.TCGETS, uintptr(unsafe.Pointer(&termios)))
	return err == 0
}

func fail(err error) {
	fmt.Fprintf(os.Stderr, "Error: %s\n", err.Error())
	os.Exit(1)
}

func main() {
	args := os.Args[1:]
	if len(args) > 0 {
		switch args[0] {
		case "completion":
			os.Exit(runCompletion(args[1:]))
		case "__complete", "__completeNoDesc":
			os.Exit(runComplete(args[1:], args[0] == "__complete"))
		}
	}

	var f Flags
	fs := defineFlags(&f)
	if err := fs.Parse(args); err != nil {
		fail(err)
	}
	if f.Help {
		fmt.Print(rootHelp(fs))
		return
	}
	if len(fs.args) > 1 {
		fail(fmt.Errorf("accepts at most 1 arg(s), received %d", len(fs.args)))
	}
	if err := run(&f, fs); err != nil {
		fail(err)
	}
}

func configPath(f *Flags) string {
	if f.CfgFile != "" {
		return f.CfgFile
	}
	home := os.Getenv("HOME")
	p := filepath.Join(home, ".config", "gdu", "gdu.yaml")
	if _, err := os.Stat(p); err == nil {
		return p
	}
	return filepath.Join(home, ".gdu.yaml")
}

func buildConfig(f *Flags, fs *FlagSet) *Config {
	c := &Config{
		Style:      defaultStyle(),
		LogFile:    "/dev/null",
		IgnoreDirs: []string{"/proc", "/dev", "/sys", "/run"},
		MaxCores:   runtime.NumCPU(),
	}
	c.IgnoreDirPatterns = []string{}
	c.Type = []string{}
	c.ExcludeType = []string{}
	if data, err := os.ReadFile(configPath(f)); err == nil {
		if m, err := parseYAML(string(data)); err == nil {
			c.applyYAML(m)
		}
	}
	ch := func(name string) bool { return fs.byName[name].Changed }
	if ch("archive-browsing") {
		c.ArchiveBrowsing = f.ArchiveBrowsing
	}
	if ch("collapse-path") {
		c.CollapsePath = f.CollapsePath
	}
	if ch("db") {
