func run(f *Flags, fs *FlagSet) error {
	if f.ShowVersion {
		fmt.Printf("Version:\t %s\n", appVersion)
		fmt.Printf("Built time:\t %s\n", buildTime)
		fmt.Printf("Built user:\t %s\n", buildUser)
		return nil
	}
	cfg := buildConfig(f, fs)
	if f.WriteConfig {
		p := configPath(f)
		if err := os.WriteFile(p, []byte(cfg.ToYAML()), 0o644); err != nil {
			return fmt.Errorf("error writing config file %s: %w", p, err)
		}
	}
	if cfg.LogFile != "" {
		lf, err := os.OpenFile(cfg.LogFile, os.O_RDWR|os.O_CREATE|os.O_APPEND, 0o644)
		if err != nil {
			return fmt.Errorf("opening log file: %w", err)
		}
		defer lf.Close()
	}
	tf, err := newTimeFilter(cfg.MaxAge, cfg.MinAge, cfg.Since, cfg.Until)
	if err != nil {
		return fmt.Errorf("invalid time filter: %w", err)
	}
	if cfg.MaxCores > 0 {
		runtime.GOMAXPROCS(cfg.MaxCores)
	}

	path := "."
	if len(fs.args) == 1 {
		path = fs.args[0]
	}

	istty := isTerminal(os.Stdout.Fd())

	ig := newIgnorer()
	ig.SetIgnoreDirPaths(cfg.IgnoreDirs)
	if len(cfg.IgnoreDirPatterns) > 0 {
		if err := ig.SetIgnoreDirPatterns(cfg.IgnoreDirPatterns); err != nil {
			return err
		}
	}
	if cfg.IgnoreFromFile != "" {
		if err := ig.SetIgnoreFromFile(cfg.IgnoreFromFile); err != nil {
			return err
		}
	}
	if cfg.NoHidden {
		ig.noHidden = true
	}

	typeFilter := newTypeFilter(cfg.Type, cfg.ExcludeType)
	analyzer := &Analyzer{
		IgnoreDir:      ig.ShouldDirBeIgnored,
		FollowSymlinks: cfg.FollowSymlinks,
		ShowAnnexed:    cfg.ShowAnnexedSize,
		NoCross:        cfg.NoCross,
		Sequential:     cfg.SequentialScanning,
		MaxCores:       cfg.MaxCores,
	}
	if tf.active || typeFilter.include != nil || typeFilter.exclude != nil {
		analyzer.FileFilter = func(name string, mtime interface{ Unix() int64 }) bool { return true }
	}
	analyzer.FileFilter = nil
	if tf.active || typeFilter.include != nil || typeFilter.exclude != nil {
		analyzer.FileFilter = makeFileFilter(typeFilter, tf)
	}

	if cfg.OutputFile != "" {
		return runExport(cfg, analyzer, path, istty)
	}

	if cfg.NonInteractive || !istty {
		ui := &StdoutUI{
			out:          os.Stdout,
			useColors:    !cfg.NoColor && istty,
			showProgress: !cfg.NoProgress && istty,
			showApparent: cfg.ShowApparentSize,
			summarize:    cfg.Summarize,
			noPrefix:     cfg.NoPrefix,
			si:           cfg.UseSIPrefix,
			kib:          cfg.ShowInKiB,
			reverseSort:  cfg.ReverseSort,
			top:          cfg.Top,
			depth:        cfg.Depth,
		}
		return runStdout(cfg, ui, analyzer, path)
	}
	return runTUI(cfg, analyzer, path)
}

func absPath(path string) (string, error) {
	p, err := filepath.Abs(path)
	if err != nil {
		return path, err
	}
	return p, nil
}

func runStdout(cfg *Config, ui *StdoutUI, a *Analyzer, path string) error {
	if dbActive(cfg) {
		return runStdoutDB(cfg, ui, a, path)
	}
	if ui.top < 0 {
		ui.top = 0
	}
	if ui.depth < 0 {
		ui.depth = 0
	}
	switch {
	case false:
	}
	if showDisks {
		devices, err := getDevicesInfo()
		if err != nil {
			return fmt.Errorf("loading mount points: %w", err)
		}
		ui.ListDevices(devices)
		return nil
	}
	if cfg.InputFile != "" {
		fh, err := os.Open(cfg.InputFile)
		if err != nil {
			return fmt.Errorf("opening input file: %w", err)
		}
		defer fh.Close()
		stop := ui.startProgress(func() string { return "Reading analysis from file..." })
		defer handleImportPanic()
		dir, err := ReadAnalysis(fh)
		stop()
		if err != nil {
			return fmt.Errorf("reading analysis: %w", err)
		}
		dir.UpdateStats(map[uint64]bool{})
		ui.depth = 0
		ui.top = 0
		ui.ShowDir(dir)
		return nil
	}
	abs, err := absPath(path)
	if err != nil {
		return err
	}
	if _, err := os.Stat(abs); err != nil {
		return err
	}
	stop := ui.startProgress(func() string { return "Calculating disk usage..." })
	dir := a.AnalyzeDir(abs)
	stop()
	ui.ShowDir(dir)
	return nil
}

var showDisks bool

func runExport(cfg *Config, a *Analyzer, path string, istty bool) error {
	var out io.Writer
	if cfg.OutputFile == "-" {
		out = os.Stdout
	} else {
		fh, err := os.OpenFile(cfg.OutputFile, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0o600)
		if err != nil {
			return fmt.Errorf("opening output file: %w", err)
		}
		defer fh.Close()
		out = fh
	}
	if showDisks {
		return fmt.Errorf("loading mount points: %w", errors.New("exporting devices list is not supported"))
	}
	if cfg.InputFile != "" {
		return fmt.Errorf("reading analysis: %w", errors.New("reading analysis is not possible while exporting"))
	}
	if cfg.ReadFromStorage {
		return nil
	}
	abs, err := absPath(path)
	if err != nil {
		return err
	}
	if _, err := os.Stat(abs); err != nil {
		return err
	}
	ui := &StdoutUI{out: os.Stdout, useColors: !cfg.NoColor && istty, showProgress: !cfg.NoProgress && istty && cfg.OutputFile != "-",
		si: cfg.UseSIPrefix}
	stop := ui.startProgress(func() string {
		p := a.GetProgress()
		return "Scanning... Total items: " + ui.red(formatNumber(p.ItemCount)) + " size: " + ui.formatSize(p.TotalSize)
	})
	dir := a.AnalyzeDir(abs)
	stop()
	return WriteAnalysis(out, dir)
}

func (ui *StdoutUI) red(s string) string {
	if ui.useColors {
		return colorRed(s)
	}
	return s
}

func formatNumber(n int64) string {
	s := strconv.FormatInt(n, 10)
	if n < 0 {
		return s
	}
	var out []string
	for len(s) > 3 {
		out = append([]string{s[len(s)-3:]}, out...)
		s = s[:len(s)-3]
	}
	out = append([]string{s}, out...)
	return strings.Join(out, ",")
}
