go build -o executable . && mkdir -p /tmp/sim && cat > /tmp/sim/main.go <<'EOF'
package main

import (
	"bufio"
	"container/heap"
	"fmt"
	"os"
	"sort"
	"strconv"
	"strings"
)

type E struct {
	size int64
	name string
	path string
}

func isDigit(c byte) bool { return c >= '0' && c <= '9' }
func naturalLess(a, b string) bool {
	for {
		if len(a) == 0 || len(b) == 0 {
			return a < b
		}
		if isDigit(a[0]) && isDigit(b[0]) {
			ia, ib := 0, 0
			var na, nb int64
			for ia < len(a) && isDigit(a[ia]) {
				na = na*10 + int64(a[ia]-'0')
				ia++
			}
			for ib < len(b) && isDigit(b[ib]) {
				nb = nb*10 + int64(b[ib]-'0')
				ib++
			}
			if na != nb {
				return na < nb
			}
			if ia != len(a) && ib != len(b) {
				a = a[ia:]
				b = b[ib:]
				continue
			}
			return a < b
		}
		if a[0] != b[0] {
			return a[0] < b[0]
		}
		a = a[1:]
		b = b[1:]
	}
}

type L []E

func (l L) Len() int      { return len(l) }
func (l L) Swap(i, j int) { l[i], l[j] = l[j], l[i] }
func (l L) Less(i, j int) bool {
	if l[i].size == l[j].size {
		return naturalLess(l[i].name, l[j].name)
	}
	return l[i].size < l[j].size
}

type LS []E // size only
func (l LS) Len() int           { return len(l) }
func (l LS) Swap(i, j int)      { l[i], l[j] = l[j], l[i] }
func (l LS) Less(i, j int) bool { return l[i].size < l[j].size }

type H struct{ L }

func (h *H) Push(x interface{}) { h.L = append(h.L, x.(E)) }
func (h *H) Pop() interface{} {
	n := len(h.L)
	x := h.L[n-1]
	h.L = h.L[:n-1]
	return x
}

type HS struct{ LS }

func (h *HS) Push(x interface{}) { h.LS = append(h.LS, x.(E)) }
func (h *HS) Pop() interface{} {
	n := len(h.LS)
	x := h.LS[n-1]
	h.LS = h.LS[:n-1]
	return x
}

func cand(id int, items []E, n int) []E {
	switch id {
	case 0, 1, 2, 3, 4, 5:
		h := &H{}
		for _, e := range items {
			if h.Len() < n {
				heap.Push(h, e)
				continue
			}
			repl := e.size > h.L[0].size
			if id >= 3 {
				repl = L{h.L[0], e}.Less(0, 1)
			}
			if !repl {
				continue
			}
			if id%3 == 0 {
				h.L[0] = e
				heap.Fix(h, 0)
			} else if id%3 == 1 {
				heap.Pop(h)
				heap.Push(h, e)
			} else {
				h.L[0] = e
				heap.Fix(h, 0)
			}
		}
		res := make([]E, h.Len())
		if id%3 == 2 {
			copy(res, h.L)
			sort.Sort(sort.Reverse(L(res)))
			return res
		}
		for i := len(res) - 1; i >= 0; i-- {
			res[i] = heap.Pop(h).(E)
		}
		return res
	case 6, 7:
		h := &H{}
		for _, e := range items {
			if h.Len() < n {
				heap.Push(h, e)
				continue
			}
			if e.size > h.L[0].size {
				heap.Pop(h)
				heap.Push(h, e)
			}
		}
		res := append([]E{}, h.L...)
		if id == 6 {
			sort.Sort(sort.Reverse(L(res)))
		} else {
			sort.Stable(sort.Reverse(L(res)))
		}
		return res
	case 8, 9:
		var res []E
		for _, e := range items {
			if len(res) < n {
				res = append(res, e)
			} else if e.size > res[len(res)-1].size {
				res[len(res)-1] = e
			} else {
				continue
			}
			if id == 8 {
				sort.Sort(sort.Reverse(L(res)))
			} else {
				sort.Slice(res, func(i, j int) bool { return L(res).Less(j, i) })
			}
		}
		return res
	case 10, 11:
		// size-only heap, then final sort
		h := &HS{}
		for _, e := range items {
			if h.Len() < n {
				heap.Push(h, e)
				continue
			}
			if e.size > h.LS[0].size {
				if id == 10 {
					h.LS[0] = e
					heap.Fix(h, 0)
				} else {
					heap.Pop(h)
					heap.Push(h, e)
				}
			}
		}
		res := append([]E{}, h.LS...)
		sort.Sort(sort.Reverse(L(res)))
		return res
	}
	return nil
}

func main() {
	n, _ := strconv.Atoi(os.Args[1])
	trav := read(os.Args[2], true)
	want := read(os.Args[3], false)
	var ok []string
	for id := 0; id < 12; id++ {
		got := cand(id, trav, n)
		match := len(got) == len(want)
		for i := 0; match && i < len(got); i++ {
			if got[i].path != want[i].path {
				match = false
			}
		}
		if match {
			ok = append(ok, strconv.Itoa(id))
		}
	}
	fmt.Println(strings.Join(ok, ","))
}

func read(p string, trav bool) []E {
	f, _ := os.Open(p)
	defer f.Close()
	var res []E
	sc := bufio.NewScanner(f)
	for sc.Scan() {
		line := sc.Text()
		if trav {
			parts := strings.SplitN(line, "\t", 3)
			sz, _ := strconv.ParseInt(parts[0], 10, 64)
			res = append(res, E{sz, parts[1], parts[2]})
		} else {
			idx := strings.Index(line, " /")
			res = append(res, E{path: line[idx+1:]})
		}
	}
	return res
}
EOF
