		for _, e := range items {
			if h.Len() < n {
				heap.Push(h, e)
				continue
			}
			if e.size > h.LS[0].size {
				if id == 10 {
					h.LS[0] = e
					heap.Fix(h, 0)
				} else {
					heap.Pop(h)
					heap.Push(h, e)
				}
			}
		}
		res := append([]E{}, h.LS...)
		sort.Sort(sort.Reverse(L(res)))
		return res
	}
	return nil
}

