var namedColors = map[string]Color{
	"black": ColorBlack, "maroon": ColorMaroon, "green": ColorGreen, "olive": ColorOlive,
	"navy": ColorNavy, "purple": ColorPurple, "teal": ColorTeal, "silver": ColorSilver,
