	"darkcyan": PaletteColor(36), "cyan": ColorAqua, "magenta": ColorFuchsia, "darkblue": PaletteColor(18),
	"darkgreen": PaletteColor(22), "darkred": PaletteColor(88), "orange": RGBColor(0xff, 0xa5, 0x00),
	"lightgray": RGBColor(0xd3, 0xd3, 0xd3), "lightgrey": RGBColor(0xd3, 0xd3, 0xd3),
	"darkgray": RGBColor(0xa9, 0xa9, 0xa9), "darkgrey": RGBColor(0xa9, 0xa9, 0xa9),
	"pink": RGBColor(0xff, 0xc0, 0xcb), "brown": RGBColor(0xa5, 0x2a, 0x2a),
	"gold": RGBColor(0xff, 0xd7, 0x00), "violet": RGBColor(0xee, 0x82, 0xee),
	"indigo": RGBColor(0x4b, 0x00, 0x82), "orchid": RGBColor(0xda, 0x70, 0xd6),
	"skyblue": RGBColor(0x87, 0xce, 0xeb), "lightblue": RGBColor(0xad, 0xd8, 0xe6),
	"lightgreen": RGBColor(0x90, 0xee, 0x90), "darkorange": RGBColor(0xff, 0x8c, 0x00),
}

// parseColor parses a color name or #rrggbb
func parseColor(s string) (Color, bool) {
	s = strings.TrimSpace(s)
	if s == "" {
		return ColorDefault, false
	}
	if strings.HasPrefix(s, "#") && len(s) == 7 {
		v, err := strconv.ParseUint(s[1:], 16, 32)
		if err != nil {
			return ColorDefault, false
		}
		return RGBColor(int(v>>16)&0xff, int(v>>8)&0xff, int(v)&0xff), true
	}
	if c, ok := namedColors[strings.ToLower(s)]; ok {
		return c, true
	}
	if strings.ToLower(s) == "default" {
		return ColorDefault, true
	}
	return ColorDefault, false
}

func paletteRGB(i int) (int, int, int) {
	basic := [16][3]int{
		{0, 0, 0}, {128, 0, 0}, {0, 128, 0}, {128, 128, 0}, {0, 0, 128}, {128, 0, 128}, {0, 128, 128}, {192, 192, 192},
		{128, 128, 128}, {255, 0, 0}, {0, 255, 0}, {255, 255, 0}, {0, 0, 255}, {255, 0, 255}, {0, 255, 255}, {255, 255, 255},
	}
	if i < 16 {
		return basic[i][0], basic[i][1], basic[i][2]
	}
	if i < 232 {
		i -= 16
		lv := []int{0, 0x5f, 0x87, 0xaf, 0xd7, 0xff}
		return lv[i/36], lv[(i/6)%6], lv[i%6]
	}
	g := 8 + (i-232)*10
	return g, g, g
}

func (c Color) RGB() (int, int, int) {
	if c.kind == 2 {
		return c.r, c.g, c.b
	}
	if c.kind == 1 {
		return paletteRGB(c.idx)
	}
	return -1, -1, -1
}

func srgbToLinear(v float64) float64 {
	if v <= 0.04045 {
		return v / 12.92
	}
	return math.Pow((v+0.055)/1.055, 2.4)
}

func labF(t float64) float64 {
	if t > 6.0/29.0*6.0/29.0*6.0/29.0 {
		return math.Cbrt(t)
	}
	return t/3.0*29.0/6.0*29.0/6.0 + 4.0/29.0
}

func toLab(r, g, b int) (float64, float64, float64) {
	rl := srgbToLinear(float64(r) / 255.0)
	gl := srgbToLinear(float64(g) / 255.0)
	bl := srgbToLinear(float64(b) / 255.0)
	x := 0.4124564*rl + 0.3575761*gl + 0.1804375*bl
	y := 0.2126729*rl + 0.7151522*gl + 0.0721750*bl
	z := 0.0193339*rl + 0.1191920*gl + 0.9503041*bl
	fx := labF(x / 0.95047)
	fy := labF(y / 1.00000)
	fz := labF(z / 1.08883)
	return 1.16*fy - 0.16, 5.0 * (fx - fy), 2.0 * (fy - fz)
}

var colorCache = map[[4]int]int{}

func findColor(c Color, n int) int {
	r, g, b := c.RGB()
	key := [4]int{r, g, b, n}
	if v, ok := colorCache[key]; ok {
		return v
	}
	l1, a1, b1 := toLab(r, g, b)
	best := -1
	bestD := 0.0
	for i := 0; i < n; i++ {
		pr, pg, pb := paletteRGB(i)
		l2, a2, b2 := toLab(pr, pg, pb)
		d := math.Sqrt((l1-l2)*(l1-l2) + (a1-a2)*(a1-a2) + (b1-b2)*(b1-b2))
		if best < 0 || d < bestD {
			best = i
			bestD = d
		}
	}
	colorCache[key] = best
	return best
}

// Attr flags
const (
	AttrBold = 1 << iota
	AttrUnderline
	AttrReverse
	AttrDim
	AttrItalic
	AttrBlink
	AttrStrike
)

// Style of a cell
type Style struct {
	fg, bg Color
	attrs  int
}

func (s Style) Fg(c Color) Style    { s.fg = c; return s }
func (s Style) Bg(c Color) Style    { s.bg = c; return s }
func (s Style) Attrs(a int) Style   { s.attrs = a; return s }
func (s Style) Bold(b bool) Style {
	if b {
		s.attrs |= AttrBold
	} else {
		s.attrs &^= AttrBold
	}
	return s
}

var StyleDefault = Style{}

type cell struct {
	ch    rune
	width int
	style Style
}

// Screen is an in-memory cell buffer flushed to the terminal
type Screen struct {
	w, h      int
	cells     []cell
	prev      []cell
	out       *os.File
	nColors   int
	truecolor bool
	buf       bytes.Buffer
	cursorX   int
	cursorY   int
	showCursor bool
}

func newScreen(out *os.File) *Screen {
	s := &Screen{out: out}
	term := os.Getenv("TERM")
	s.nColors = 8
	if strings.Contains(term, "256color") {
		s.nColors = 256
	} else if term == "" || term == "dumb" {
		s.nColors = 8
	} else if strings.HasPrefix(term, "xterm") || strings.HasPrefix(term, "rxvt") || strings.HasPrefix(term, "konsole") || strings.HasPrefix(term, "linux") || strings.HasPrefix(term, "screen") || strings.HasPrefix(term, "tmux") || strings.HasPrefix(term, "vt") {
		s.nColors = 8
	}
	if term == "xterm" {
		s.nColors = 8
	}
	if strings.HasPrefix(term, "xterm-direct") || strings.HasSuffix(term, "-truecolor") {
		s.nColors = 256
		s.truecolor = true
	}
	ct := os.Getenv("COLORTERM")
	if (ct == "truecolor" || ct == "24bit") && s.nColors >= 256 {
		s.truecolor = true
	}
	if os.Getenv("TCELL_TRUECOLOR") == "disable" {
		s.truecolor = false
	}
	return s
}

func (s *Screen) Resize(w, h int) {
	s.w, s.h = w, h
	s.cells = make([]cell, w*h)
	s.prev = nil
	s.Clear()
}

func (s *Screen) Size() (int, int) { return s.w, s.h }

func (s *Screen) Clear() {
	for i := range s.cells {
		s.cells[i] = cell{ch: ' ', width: 1, style: StyleDefault}
	}
}

func (s *Screen) SetContent(x, y int, ch rune, st Style) {
	if x < 0 || y < 0 || x >= s.w || y >= s.h {
		return
	}
	s.cells[y*s.w+x] = cell{ch: ch, width: 1, style: st}
}

func (s *Screen) SetWide(x, y int, ch rune, w int, st Style) {
	if x < 0 || y < 0 || x >= s.w || y >= s.h {
		return
	}
	s.cells[y*s.w+x] = cell{ch: ch, width: w, style: st}
	for i := 1; i < w && x+i < s.w; i++ {
		s.cells[y*s.w+x+i] = cell{ch: 0, width: 0, style: st}
	}
}

func (s *Screen) GetContent(x, y int) (rune, Style) {
	if x < 0 || y < 0 || x >= s.w || y >= s.h {
		return ' ', StyleDefault
	}
	c := s.cells[y*s.w+x]
	return c.ch, c.style
}

func (s *Screen) SetStyleAt(x, y int, st Style) {
	if x < 0 || y < 0 || x >= s.w || y >= s.h {
		return
	}
	s.cells[y*s.w+x].style = st
}

func (s *Screen) colorSeq(c Color, fg bool) string {
	if c.kind == 0 {
		return ""
	}
	if c.kind == 2 {
		if s.truecolor {
			if fg {
				return fmt.Sprintf("\x1b[38;2;%d;%d;%dm", c.r, c.g, c.b)
			}
			return fmt.Sprintf("\x1b[48;2;%d;%d;%dm", c.r, c.g, c.b)
		}
		return s.paletteSeq(findColor(c, s.nColors), fg)
	}
	idx := c.idx
	if idx >= s.nColors {
		idx = findColor(c, s.nColors)
	}
	return s.paletteSeq(idx, fg)
}

func (s *Screen) paletteSeq(idx int, fg bool) string {
	base := 30
	if !fg {
		base = 40
	}
	if idx < 8 {
		return fmt.Sprintf("\x1b[%dm", base+idx)
	}
	if idx < 16 && s.nColors >= 16 {
		return fmt.Sprintf("\x1b[%dm", base+60+idx-8)
	}
	if fg {
		return fmt.Sprintf("\x1b[38;5;%dm", idx)
	}
	return fmt.Sprintf("\x1b[48;5;%dm", idx)
}

func (s *Screen) styleSeq(st Style) string {
	var sb strings.Builder
	sb.WriteString("\x1b[0m")
	if st.attrs&AttrBold != 0 {
		sb.WriteString("\x1b[1m")
	}
	if st.attrs&AttrDim != 0 {
		sb.WriteString("\x1b[2m")
	}
	if st.attrs&AttrItalic != 0 {
		sb.WriteString("\x1b[3m")
	}
	if st.attrs&AttrUnderline != 0 {
		sb.WriteString("\x1b[4m")
	}
	if st.attrs&AttrBlink != 0 {
		sb.WriteString("\x1b[5m")
	}
	if st.attrs&AttrReverse != 0 {
		sb.WriteString("\x1b[7m")
	}
	if st.attrs&AttrStrike != 0 {
		sb.WriteString("\x1b[9m")
	}
	sb.WriteString(s.colorSeq(st.fg, true))
	sb.WriteString(s.colorSeq(st.bg, false))
	return sb.String()
}

// Show flushes changes to the terminal
func (s *Screen) Show() {
	s.buf.Reset()
	full := s.prev == nil || len(s.prev) != len(s.cells)
	if full {
		s.buf.WriteString("\x1b[0m\x1b[H\x1b[2J")
		s.prev = make([]cell, len(s.cells))
		for i := range s.prev {
			s.prev[i] = cell{ch: ' ', width: 1}
		}
	}
	var cur Style
	curSet := false
	lastX, lastY := -1, -1
	var tmp [4]byte
	for y := 0; y < s.h; y++ {
		for x := 0; x < s.w; x++ {
			i := y*s.w + x
			c := s.cells[i]
			if !full && c == s.prev[i] {
				continue
			}
			if c.width == 0 {
				s.prev[i] = c
				continue
			}
			if lastY != y || lastX != x {
				fmt.Fprintf(&s.buf, "\x1b[%d;%dH", y+1, x+1)
			}
			if !curSet || c.style != cur {
				s.buf.WriteString(s.styleSeq(c.style))
				cur = c.style
				curSet = true
			}
			ch := c.ch
			if ch == 0 {
				ch = ' '
			}
			n := utf8.EncodeRune(tmp[:], ch)
			s.buf.Write(tmp[:n])
			s.prev[i] = c
			w := c.width
			if w < 1 {
				w = 1
			}
			lastX, lastY = x+w, y
			if lastX >= s.w {
				lastX = -1
			}
		}
	}
	if s.buf.Len() > 0 {
		s.buf.WriteString("\x1b[0m")
		if s.showCursor {
			fmt.Fprintf(&s.buf, "\x1b[%d;%dH\x1b[?25h", s.cursorY+1, s.cursorX+1)
		} else {
			s.buf.WriteString("\x1b[?25l")
		}
		s.out.Write(s.buf.Bytes())
	} else if s.showCursor {
		fmt.Fprintf(s.out, "\x1b[%d;%dH\x1b[?25h", s.cursorY+1, s.cursorX+1)
	}
}

func (s *Screen) Invalidate() { s.prev = nil }
