package main

import (
	"os"
	"os/signal"
	"syscall"
	"time"
	"unicode/utf8"
	"unsafe"
)

// Key codes
const (
	KeyRune = iota
	KeyUp
	KeyDown
	KeyLeft
	KeyRight
	KeyEnter
	KeyEsc
	KeyBackspace
	KeyTab
	KeyBacktab
	KeyHome
	KeyEnd
	KeyPgUp
	KeyPgDn
	KeyDelete
	KeyInsert
	KeyCtrl // with Rune = letter
	KeyF
	KeyMouse
	KeyResize
	KeyUnknown
)

// Event from terminal
type Event struct {
	Key  int
	Rune rune
	Alt  bool
	// mouse
	MouseX, MouseY int
	MouseBtn       int
	MousePress     bool
}

type Terminal struct {
	in       *os.File
	out      *os.File
	orig     syscall.Termios
	events   chan Event
	resize   chan os.Signal
	stopRead chan struct{}
	mouse    bool
}

func ioctlTermios(fd uintptr, req uintptr, t *syscall.Termios) error {
	_, _, e := syscall.Syscall(syscall.SYS_IOCTL, fd, req, uintptr(unsafe.Pointer(t)))
	if e != 0 {
		return e
	}
	return nil
}

type winsize struct {
	Row, Col, X, Y uint16
}

func termSize(fd uintptr) (int, int) {
	var ws winsize
	_, _, e := syscall.Syscall(syscall.SYS_IOCTL, fd, syscall.TIOCGWINSZ, uintptr(unsafe.Pointer(&ws)))
	if e != 0 || ws.Col == 0 || ws.Row == 0 {
		return 80, 24
	}
	return int(ws.Col), int(ws.Row)
}

func openTerminal(mouse bool) (*Terminal, error) {
	in := os.Stdin
	if !isTerminal(in.Fd()) {
		f, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
		if err != nil {
			return nil, err
		}
		in = f
	}
	t := &Terminal{in: in, out: os.Stdout, events: make(chan Event, 256), mouse: mouse}
	if err := ioctlTermios(in.Fd(), syscall.TCGETS, &t.orig); err != nil {
		return nil, err
	}
	raw := t.orig
	raw.Iflag &^= syscall.IGNBRK | syscall.BRKINT | syscall.PARMRK | syscall.ISTRIP | syscall.INLCR | syscall.IGNCR | syscall.ICRNL | syscall.IXON
	raw.Oflag &^= syscall.OPOST
	raw.Lflag &^= syscall.ECHO | syscall.ECHONL | syscall.ICANON | syscall.ISIG | syscall.IEXTEN
	raw.Cflag &^= syscall.CSIZE | syscall.PARENB
	raw.Cflag |= syscall.CS8
	raw.Cc[syscall.VMIN] = 1
	raw.Cc[syscall.VTIME] = 0
	if err := ioctlTermios(in.Fd(), syscall.TCSETS, &raw); err != nil {
		return nil, err
	}
	// enter alt screen, keypad mode, hide cursor
	seq := "\x1b[?1049h\x1b[?1h\x1b=\x1b[?25l\x1b[0m\x1b[H\x1b[2J"
	if mouse {
		seq += "\x1b[?1000h\x1b[?1002h\x1b[?1006h"
	}
	t.out.WriteString(seq)
	t.resize = make(chan os.Signal, 1)
	signal.Notify(t.resize, syscall.SIGWINCH)
	go t.readLoop()
	go func() {
		for range t.resize {
			t.events <- Event{Key: KeyResize}
		}
	}()
	return t, nil
}

// Suspend restores terminal for running subprocess
func (t *Terminal) Suspend() {
	seq := ""
	if t.mouse {
		seq += "\x1b[?1006l\x1b[?1002l\x1b[?1000l"
	}
	seq += "\x1b[0m\x1b[H\x1b[2J\x1b[?25h\x1b[?1l\x1b>\x1b[?1049l"
	t.out.WriteString(seq)
	ioctlTermios(t.in.Fd(), syscall.TCSETS, &t.orig)
}

// Resume re-enters raw mode
func (t *Terminal) Resume() {
	raw := t.orig
	raw.Iflag &^= syscall.IGNBRK | syscall.BRKINT | syscall.PARMRK | syscall.ISTRIP | syscall.INLCR | syscall.IGNCR | syscall.ICRNL | syscall.IXON
	raw.Oflag &^= syscall.OPOST
	raw.Lflag &^= syscall.ECHO | syscall.ECHONL | syscall.ICANON | syscall.ISIG | syscall.IEXTEN
	raw.Cflag &^= syscall.CSIZE | syscall.PARENB
	raw.Cflag |= syscall.CS8
	raw.Cc[syscall.VMIN] = 1
	raw.Cc[syscall.VTIME] = 0
	ioctlTermios(t.in.Fd(), syscall.TCSETS, &raw)
	seq := "\x1b[?1049h\x1b[?1h\x1b=\x1b[?25l\x1b[0m\x1b[H\x1b[2J"
	if t.mouse {
		seq += "\x1b[?1000h\x1b[?1002h\x1b[?1006h"
	}
	t.out.WriteString(seq)
}

func (t *Terminal) Close() {
	signal.Stop(t.resize)
	t.Suspend()
}

func (t *Terminal) readLoop() {
	buf := make([]byte, 4096)
	var pending []byte
	data := make(chan []byte, 16)
	go func() {
		for {
			n, err := t.in.Read(buf)
			if err != nil || n <= 0 {
				if err != nil {
					close(data)
					return
				}
				continue
			}
			b := make([]byte, n)
			copy(b, buf[:n])
			data <- b
		}
	}()
	for {
		var timeout <-chan time.Time
		if len(pending) > 0 {
			timeout = time.After(50 * time.Millisecond)
		}
		select {
		case b, ok := <-data:
			if !ok {
				return
			}
			pending = append(pending, b...)
			pending = t.parse(pending, false)
		case <-timeout:
			pending = t.parse(pending, true)
		}
	}
}

func (t *Terminal) emit(e Event) { t.events <- e }

// parse consumes as many events as possible from b
func (t *Terminal) parse(b []byte, flush bool) []byte {
	for len(b) > 0 {
		c := b[0]
		if c == 0x1b {
			if len(b) == 1 {
				if flush {
					t.emit(Event{Key: KeyEsc})
