package main

import (
	"regexp"
	"strings"
	"unicode"
)

var colorTagRe = regexp.MustCompile(`\[([a-zA-Z]+|#[0-9a-zA-Z]{6}|\-)?(:([a-zA-Z]+|#[0-9a-zA-Z]{6}|\-)?(:([lbidrus]+|\-)?)?)?\]`)
var escapedTagRe = regexp.MustCompile(`\[([a-zA-Z0-9_,;: \-\."#]+)\[(\[*)\]`)
var nonEscapeRe = regexp.MustCompile(`(\[[a-zA-Z0-9_,;: \-\."#]+\[*)\]`)

// tviewEscape escapes text so tags are printed literally
func tviewEscape(s string) string {
	return nonEscapeRe.ReplaceAllString(s, "$1[]")
}

// runeWidth returns the display width of r
func runeWidth(r rune) int {
	if r == 0 {
		return 0
	}
	if r < 32 || (r >= 0x7f && r < 0xa0) {
		return 0
	}
	if unicode.Is(unicode.Mn, r) || unicode.Is(unicode.Me, r) || r == 0x200B {
		return 0
	}
	if isWide(r) {
		return 2
	}
	return 1
}

func isWide(r rune) bool {
	return (r >= 0x1100 && r <= 0x115F) || r == 0x2329 || r == 0x232A ||
		(r >= 0x2E80 && r <= 0x303E) || (r >= 0x3041 && r <= 0x33FF) ||
		(r >= 0x3400 && r <= 0x4DBF) || (r >= 0x4E00 && r <= 0x9FFF) ||
		(r >= 0xA000 && r <= 0xA4CF) || (r >= 0xAC00 && r <= 0xD7A3) ||
		(r >= 0xF900 && r <= 0xFAFF) || (r >= 0xFE30 && r <= 0xFE4F) ||
		(r >= 0xFF00 && r <= 0xFF60) || (r >= 0xFFE0 && r <= 0xFFE6) ||
		(r >= 0x1F300 && r <= 0x1F64F) || (r >= 0x1F900 && r <= 0x1F9FF) ||
		(r >= 0x20000 && r <= 0x3FFFD)
}

func stringWidth(s string) int {
	w := 0
	for _, r := range s {
		w += runeWidth(r)
	}
	return w
}

// styledRune is a rune with its resolved style
type styledRune struct {
	r     rune
	w     int
	style Style
}

func applyAttrFlags(flags string) int {
	a := 0
	for _, c := range flags {
		switch c {
		case 'b':
			a |= AttrBold
		case 'u':
			a |= AttrUnderline
		case 'r':
			a |= AttrReverse
		case 'd':
			a |= AttrDim
		case 'i':
			a |= AttrItalic
		case 'l':
			a |= AttrBlink
		case 's':
			a |= AttrStrike
		}
	}
	return a
}

// parseTagged converts a tview-tagged string into styled runes, starting with base style
func parseTagged(text string, base Style) []styledRune {
	var res []styledRune
	fg, bg, attrs := "", "", ""
	cur := base
	recompute := func() {
		st := base
		if fg == "-" {
			st.fg = base.fg
		} else if fg != "" {
			if c, ok := parseColor(fg); ok {
				st.fg = c
			}
		}
		if bg == "-" {
			st.bg = base.bg
		} else if bg != "" {
			if c, ok := parseColor(bg); ok {
				st.bg = c
			}
		}
		if attrs == "-" {
			st.attrs = base.attrs
		} else if attrs != "" {
			st.attrs = applyAttrFlags(attrs)
		}
		cur = st
	}
	i := 0
	for i < len(text) {
		if text[i] == '[' {
			rest := text[i:]
			if loc := colorTagRe.FindStringSubmatchIndex(rest); loc != nil && loc[0] == 0 {
				m := colorTagRe.FindStringSubmatch(rest)
				if m[1] != "" {
					fg = m[1]
				}
				if m[3] != "" {
					bg = m[3]
				}
				if m[5] != "" {
					attrs = m[5]
				}
				recompute()
				i += loc[1]
				continue
			}
			if loc := escapedTagRe.FindStringSubmatchIndex(rest); loc != nil && loc[0] == 0 {
				m := escapedTagRe.FindStringSubmatch(rest)
				lit := "[" + m[1] + m[2] + "]"
				for _, r := range lit {
					res = append(res, styledRune{r, runeWidth(r), cur})
				}
				i += loc[1]
				continue
			}
		}
		r, sz := decodeRune(text[i:])
		res = append(res, styledRune{r, runeWidth(r), cur})
		i += sz
	}
	return res
}

func decodeRune(s string) (rune, int) {
	for i, r := range s {
		_ = i
		return r, len(string(r))
	}
	return 0, 1
}

func taggedWidth(text string) int {
	w := 0
	for _, sr := range parseTagged(text, StyleDefault) {
		w += sr.w
	}
	return w
}

// stripTags returns text without tags
func stripTags(text string) string {
	var sb strings.Builder
	for _, sr := range parseTagged(text, StyleDefault) {
		sb.WriteRune(sr.r)
	}
	return sb.String()
}

const (
	AlignLeft = iota
	AlignCenter
	AlignRight
)

// printRunes prints styled runes at x,y within maxWidth; returns printed width
func printRunes(scr *Screen, runes []styledRune, x, y, maxWidth, align int, maintainBg bool) int {
	total := 0
	for _, r := range runes {
		total += r.w
	}
	if align == AlignRight {
		if total <= maxWidth {
			return printRunes(scr, runes, x+maxWidth-total, y, total, AlignLeft, maintainBg)
		}
		// trim from beginning
		for total > maxWidth && len(runes) > 0 {
			total -= runes[0].w
			runes = runes[1:]
		}
		return printRunes(scr, runes, x, y, maxWidth, AlignLeft, maintainBg)
	}
	if align == AlignCenter {
		if total == maxWidth {
			return printRunes(scr, runes, x, y, maxWidth, AlignLeft, maintainBg)
		} else if total < maxWidth {
			half := (maxWidth - total) / 2
			return printRunes(scr, runes, x+half, y, maxWidth-half, AlignLeft, maintainBg)
		}
		choppedLeft, choppedRight := 0, 0
		left, right := 0, len(runes)
		for right-1 > left && total-choppedLeft-choppedRight > maxWidth {
			if choppedLeft < choppedRight {
				choppedLeft += runes[left].w
				left++
			} else {
				right--
				choppedRight += runes[right].w
			}
		}
		return printRunes(scr, runes[left:right], x, y, maxWidth, AlignLeft, maintainBg)
	}
	printed := 0
	for _, r := range runes {
		if r.w == 0 {
			continue
		}
		if printed+r.w > maxWidth {
			break
		}
		st := r.style
		if maintainBg && st.bg.kind == 0 {
			_, ex := scr.GetContent(x+printed, y)
			st.bg = ex.bg
		}
		if r.w == 2 {
			scr.SetWide(x+printed, y, r.r, 2, st)
		} else {
			scr.SetContent(x+printed, y, r.r, st)
		}
		printed += r.w
	}
	return printed
}

// printTagged prints a tagged string
func printTagged(scr *Screen, text string, x, y, maxWidth, align int, base Style, maintainBg bool) int {
	return printRunes(scr, parseTagged(text, base), x, y, maxWidth, align, maintainBg)
}

// wordWrapLines splits styled runes into lines of at most width, breaking after spaces when possible
func wordWrapRunes(runes []styledRune, width int) [][]styledRune {
	var lines [][]styledRune
	for len(runes) > 0 {
		w := 0
		cut := -1
		lastBreak := -1
		for i, r := range runes {
			if w+r.w > width {
				cut = i
				break
			}
			w += r.w
			if r.r == ' ' {
				lastBreak = i + 1
			}
		}
		if cut < 0 {
			lines = append(lines, runes)
			break
		}
		if lastBreak > 0 {
			cut = lastBreak
		}
		if cut == 0 {
			cut = 1
		}
		lines = append(lines, runes[:cut])
		runes = runes[cut:]
	}
	return lines
}

// Borders
type borderSet struct {
	h, v, tl, tr, bl, br rune
}

var bordersNormal = borderSet{'─', '│', '┌', '┐', '└', '┘'}
var bordersFocus = borderSet{'═', '║', '╔', '╗', '╚', '╝'}

// drawBox fills the rectangle with bg and draws a border with a title
func drawBox(scr *Screen, x, y, w, h int, bg Style, border bool, focus bool, borderStyle Style, title string, titleStyle Style) {
	if w <= 0 || h <= 0 {
		return
	}
	for yy := y; yy < y+h; yy++ {
		for xx := x; xx < x+w; xx++ {
			scr.SetContent(xx, yy, ' ', bg)
		}
	}
	if !border || w < 2 || h < 2 {
		return
	}
	b := bordersNormal
	if focus {
		b = bordersFocus
	}
	for xx := x + 1; xx < x+w-1; xx++ {
		scr.SetContent(xx, y, b.h, borderStyle)
		scr.SetContent(xx, y+h-1, b.h, borderStyle)
	}
	for yy := y + 1; yy < y+h-1; yy++ {
		scr.SetContent(x, yy, b.v, borderStyle)
		scr.SetContent(x+w-1, yy, b.v, borderStyle)
	}
	scr.SetContent(x, y, b.tl, borderStyle)
	scr.SetContent(x+w-1, y, b.tr, borderStyle)
	scr.SetContent(x, y+h-1, b.bl, borderStyle)
	scr.SetContent(x+w-1, y+h-1, b.br, borderStyle)
	if title != "" && w >= 4 {
		runes := parseTagged(title, titleStyle)
		printed := printRunes(scr, runes, x+1, y, w-2, AlignCenter, true)
		tw := 0
		for _, r := range runes {
			tw += r.w
		}
		if tw-printed > 0 && printed > 0 {
			_, st := scr.GetContent(x+w-2, y)
			scr.SetContent(x+w-2, y, '…', st)
		}
	}
}
