		}
		if lastBreak > 0 {
			cut = lastBreak
		}
		if cut == 0 {
			cut = 1
		}
		lines = append(lines, runes[:cut])
		runes = runes[cut:]
	}
	return lines
}

// Borders
type borderSet struct {
	h, v, tl, tr, bl, br rune
}

var bordersNormal = borderSet{'─', '│', '┌', '┐', '└', '┘'}
var bordersFocus = borderSet{'═', '║', '╔', '╗', '╚', '╝'}

// drawBox fills the rectangle with bg and draws a border with a title
func drawBox(scr *Screen, x, y, w, h int, bg Style, border bool, focus bool, borderStyle Style, title string, titleStyle Style) {
