cd /workspace && cat > tui_app.go <<'EOF'
package main

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"sort"
	"strings"
	"sync"
	"time"
)

type modal interface {
	Draw(t *TUI)
	HandleEvent(t *TUI, ev Event) bool // returns true if consumed
}

// TUI is the interactive user interface
type TUI struct {
	cfg      *Config
	analyzer *Analyzer
	scr      *Screen
	term     *Terminal

	useColors        bool
	showApparentSize bool
	showRelativeSize bool
	showItemCount    bool
	showMtime        bool
	noDelete         bool
	noSpawnShell     bool
	noUnicode        bool
	useSI            bool
	collapsePath     bool

	topDir      *Dir
	currentDir  *Dir
	devices     []*Device
	showDevices bool

	sortBy    string
	sortOrder string

	rows      []Item // items displayed (excluding "..")
	hasParent bool
	selected  int
	offset    int

	markedRows map[Item]bool
	ignored    map[string]bool
	askBeforeDelete bool

	filterValue  string
	filtering    bool // input field focused
	filterShown  bool
	filterCursor int

	modals []modal

	quit     bool
	printCwd bool
	mu       sync.Mutex
	redraw   chan struct{}
	tasks    chan func()

	scanning     bool
	scanStart    time.Time

	// styles
	selectedStyle Style
	headerStyle   Style
	footerStyle   Style
	footerNum     Style
	numberColor   string
	dirColor      string
	headerHidden  bool
}

func newTUI(cfg *Config, a *Analyzer) *TUI {
	t := &TUI{
		cfg:              cfg,
		analyzer:         a,
		useColors:        !cfg.NoColor,
		showApparentSize: cfg.ShowApparentSize,
		showRelativeSize: cfg.ShowRelativeSize,
		showItemCount:    cfg.ShowItemCount,
		showMtime:        cfg.ShowMTime,
		noDelete:         cfg.NoDelete,
		noSpawnShell:     cfg.NoSpawnShell,
		noUnicode:        cfg.NoUnicode,
		useSI:            cfg.UseSIPrefix,
		collapsePath:     cfg.CollapsePath,
		sortBy:           "size",
		sortOrder:        "desc",
		markedRows:       map[Item]bool{},
		ignored:          map[string]bool{},
		askBeforeDelete:  true,
		redraw:           make(chan struct{}, 1),
		tasks:            make(chan func(), 64),
		headerHidden:     cfg.Style.HeaderHidden,
	}
	switch cfg.SortBy {
	case "name", "size", "itemCount", "mtime":
		t.sortBy = cfg.SortBy
	}
	if cfg.SortOrder == "asc" || cfg.SortOrder == "desc" {
		t.sortOrder = cfg.SortOrder
	}
	st := cfg.Style
	t.numberColor = st.ResultNumberColor
	t.dirColor = st.ResultDirectoryColor
	if t.useColors {
		t.selectedStyle = StyleDefault.Fg(ColorWhite).Bg(ColorGreen).Attrs(AttrBold)
	} else {
		t.selectedStyle = StyleDefault.Fg(ColorWhite).Bg(ColorGray).Attrs(AttrBold)
	}
	if c, ok := parseColor(st.SelectedTextColor); ok {
		t.selectedStyle.fg = c
	}
	if c, ok := parseColor(st.SelectedBgColor); ok {
		t.selectedStyle.bg = c
	}
	hfg, _ := parseColor(st.HeaderTextColor)
	hbg, _ := parseColor(st.HeaderBgColor)
	t.headerStyle = StyleDefault.Fg(hfg).Bg(hbg)
	if t.useColors {
		ffg, _ := parseColor(st.FooterTextColor)
		fbg, _ := parseColor(st.FooterBgColor)
		fnum, _ := parseColor(st.FooterNumberColor)
		t.footerStyle = StyleDefault.Fg(ffg).Bg(fbg)
		t.footerNum = StyleDefault.Fg(fnum).Bg(fbg).Attrs(AttrBold)
	} else {
		t.footerStyle = StyleDefault.Fg(ColorBlack).Bg(ColorWhite)
		t.footerNum = StyleDefault.Fg(ColorBlack).Bg(ColorWhite).Attrs(AttrBold)
	}
	return t
}

func (t *TUI) requestRedraw() {
	select {
	case t.redraw <- struct{}{}:
	default:
	}
}

func (t *TUI) post(f func()) {
	t.tasks <- f
	t.requestRedraw()
}

// ---------- size formatting ----------

func (t *TUI) numTag() string {
	return "[" + t.numberColor + "::b]"
}

// formatSize returns tagged size string; transparent controls the reset tag
func (t *TUI) formatSize(size int64, reverseColor bool, transparentBg bool) string {
	n, u := formatSizeParts(size, t.useSI)
	color := "[-::]"
	if reverseColor {
		color = "[black:white:-]"
	} else if !transparentBg {
		color = "[white:black:-]"
	}
	return n + color + " " + u
}

// ---------- table rows ----------

func (t *TUI) maxValues() (int64, int64) {
	var maxUsage, maxSize int64
	if t.showRelativeSize {
		for _, it := range t.rows {
			if it.GetUsage() > maxUsage {
				maxUsage = it.GetUsage()
			}
			if it.GetSize() > maxSize {
				maxSize = it.GetSize()
			}
		}
	} else {
		for _, it := range t.rows {
			maxUsage += it.GetUsage()
			maxSize += it.GetSize()
		}
	}
	return maxUsage, maxSize
}

func usageGraph(part int, noUnicode bool) string {
	if noUnicode {
		g := strings.Repeat("#", part/10)
		return g + strings.Repeat(" ", 10-len([]rune(g))) + "|"
	}
	g := ""
	full := part / 10
	if full > 10 {
		full = 10
	}
	if full < 0 {
		full = 0
	}
	g = strings.Repeat("█", full)
	if full < 10 {
		switch part % 10 {
		case 3:
			g += "▎"
		case 4:
			g += "▍"
		case 5, 6:
			g += "▌"
		case 7:
			g += "▋"
		case 8:
			g += "▊"
		case 9:
			g += "▉"
		}
	}
	n := len([]rune(g))
	if n < 10 {
		g += strings.Repeat(" ", 10-n)
	}
	return g + "▏"
}

func (t *TUI) formatFileRow(item Item, maxUsage, maxSize int64, marked, ignored bool) string {
	part := 0
	if t.showApparentSize {
		if s := item.GetSize(); s > 0 && maxSize > 0 {
			part = int(float64(s) / float64(maxSize) * 100.0)
		}
	} else {
		if u := item.GetUsage(); u > 0 && maxUsage > 0 {
			part = int(float64(u) / float64(maxUsage) * 100.0)
		}
	}
	row := string(item.GetFlag())
	colored := t.useColors && !marked && !ignored
	if colored {
		row += t.numTag()
	} else {
		row += "[::b]"
	}
	if t.showApparentSize {
		row += fmt.Sprintf("%15s", t.formatSize(item.GetSize(), false, true))
	} else {
		row += fmt.Sprintf("%15s", t.formatSize(item.GetUsage(), false, true))
	}
	row += usageGraph(part, t.noUnicode)
	if t.showItemCount {
		if colored {
			row += t.numTag()
		} else {
			row += "[::b]"
		}
		row += fmt.Sprintf("%11s ", fmt.Sprintf("%d", t.displayCount(item))+"[-::]")
	}
	if t.showMtime {
		if colored {
			row += t.numTag()
		} else {
			row += "[::b]"
		}
		row += fmt.Sprintf("%s [-::]", item.GetMtime().Format("2006-01-02 15:04:05"))
	}
	if len(t.markedRows) > 0 {
		if marked {
			row += "✓"
		} else {
			row += " "
		}
		row += " "
	}
	if item.IsDir() {
		if colored {
			row += "[" + t.dirColor + "::b]/"
		} else {
			row += "[::b]/"
		}
	}
	row += tviewEscape(item.GetName())
	return row
}

func (t *TUI) displayCount(item Item) int {
	if item.IsDir() {
		return item.GetItemCount() - 1
	}
	return item.GetItemCount()
}

// ---------- sorting ----------

type tuiSorter struct {
	items []Item
	less  func(a, b Item) bool
}

func (s tuiSorter) Len() int           { return len(s.items) }
func (s tuiSorter) Swap(i, j int)      { s.items[i], s.items[j] = s.items[j], s.items[i] }
func (s tuiSorter) Less(i, j int) bool { return s.less(s.items[i], s.items[j]) }

func (t *TUI) sortItems(items []Item) {
	var less func(a, b Item) bool
	switch t.sortBy {
	case "name":
		less = func(a, b Item) bool { return naturalLess(a.GetName(), b.GetName()) }
	case "itemCount":
		less = func(a, b Item) bool {
			if a.GetItemCount() == b.GetItemCount() {
				return naturalLess(a.GetName(), b.GetName())
			}
			return a.GetItemCount() < b.GetItemCount()
		}
	case "mtime":
		less = func(a, b Item) bool {
			if a.GetMtime().Equal(b.GetMtime()) {
				return naturalLess(a.GetName(), b.GetName())
			}
			return a.GetMtime().Before(b.GetMtime())
		}
	default:
		if t.showApparentSize {
			less = func(a, b Item) bool {
				if a.GetSize() == b.GetSize() {
					return naturalLess(a.GetName(), b.GetName())
				}
				return a.GetSize() < b.GetSize()
			}
		} else {
			less = func(a, b Item) bool {
				if a.GetUsage() == b.GetUsage() {
					return naturalLess(a.GetName(), b.GetName())
				}
				return a.GetUsage() < b.GetUsage()
			}
		}
	}
	s := tuiSorter{items, less}
	if t.sortOrder == "desc" {
		sort.Sort(sort.Reverse(s))
	} else {
		sort.Sort(s)
	}
}

// ---------- directory display ----------

func (t *TUI) filteredItems() []Item {
	dir := t.currentDir
	t.sortItems(dir.Files)
	var res []Item
	for _, it := range dir.Files {
		if t.filterValue != "" && !strings.Contains(strings.ToLower(it.GetName()), strings.ToLower(t.filterValue)) {
			continue
		}
		res = append(res, it)
	}
	return res
}

func (t *TUI) showDir(selectItem Item) {
	if t.currentDir == nil {
		return
	}
	t.hasParent = t.currentDir != t.topDir && t.currentDir.Parent != nil
	t.rows = t.filteredItems()
	t.selected = 0
	t.offset = 0
	if selectItem != nil {
		for i, it := range t.rows {
			if it == selectItem {
				t.selected = i
				if t.hasParent {
					t.selected++
				}
				break
			}
		}
	}
}

func (t *TUI) rowCount() int {
	n := len(t.rows)
	if t.hasParent {
		n++
	}
	return n
}

func (t *TUI) rowItem(i int) Item {
	if t.hasParent {
		if i == 0 {
			return nil
		}
		i--
	}
	if i < 0 || i >= len(t.rows) {
		return nil
	}
	return t.rows[i]
}

func (t *TUI) selectedItem() Item { return t.rowItem(t.selected) }

func (t *TUI) dirPath(d *Dir) string {
	return d.GetPath()
}

// ---------- drawing ----------

func (t *TUI) tableRect() (int, int, int, int) {
	w, h := t.scr.Size()
	top := 2
	if t.headerHidden {
		top = 1
	}
	return 0, top, w, h - top - 1
}

func (t *TUI) rowText(i int, maxUsage, maxSize int64) (string, Style) {
	it := t.rowItem(i)
	if it == nil {
		return "                         [::b]/..", StyleDefault
	}
	marked := t.markedRows[it]
	ignored := t.ignored[it.GetPath()]
	st := StyleDefault
	if marked {
		st = StyleDefault.Fg(ColorWhite).Bg(ColorBlue)
	} else if ignored {
		st = StyleDefault.Fg(ColorWhite).Bg(ColorGray)
	}
	return t.formatFileRow(it, maxUsage, maxSize, marked, ignored), st
}

func (t *TUI) drawTable() {
	x, y, width, height := t.tableRect()
	n := t.rowCount()
	if height <= 0 {
		return
	}
	// adjust offset so selected row is visible
	if t.selected >= n {
		t.selected = n - 1
	}
	if t.selected < 0 {
		t.selected = 0
	}
	if t.offset > n-height {
		t.offset = n - height
	}
	if t.offset < 0 {
		t.offset = 0
	}
	if t.selected < t.offset {
		t.offset = t.selected
	}
	if t.selected >= t.offset+height {
		t.offset = t.selected - height + 1
	}
	maxUsage, maxSize := t.maxValues()
	type rowInfo struct {
		runes []styledRune
		style Style
	}
	var vis []rowInfo
	colWidth := 0
	for r := t.offset; r < n && r < t.offset+height; r++ {
		text, st := t.rowText(r, maxUsage, maxSize)
		runes := parseTagged(text, st)
		w := 0
		for _, sr := range runes {
			w += sr.w
		}
		if w > colWidth {
			colWidth = w
		}
		vis = append(vis, rowInfo{runes, st})
	}
	finalWidth := colWidth
	if 1+colWidth >= width+1 {
		finalWidth = width
	}
	if finalWidth > width {
		finalWidth = width
	}
	for i, ri := range vis {
		ry := y + i
		printed := printRunes(t.scr, ri.runes, x, ry, finalWidth, AlignLeft, false)
		total := 0
		for _, sr := range ri.runes {
			total += sr.w
		}
		if total-printed > 0 && printed > 0 {
			_, st := t.scr.GetContent(x+finalWidth-1, ry)
			t.scr.SetContent(x+finalWidth-1, ry, '…', st)
		}
		// background of the cell box
		rowIdx := t.offset + i
		bw := colWidth + 1
		if rowIdx == t.selected && !t.filtering {
			for bx := 0; bx < bw && x+bx < x+width; bx++ {
				ch, _ := t.scr.GetContent(x+bx, ry)
				t.scr.SetContent(x+bx, ry, ch, t.selectedStyle)
			}
		} else if ri.style.bg.kind != 0 {
			for bx := 0; bx < bw && x+bx < x+width; bx++ {
				ch, cst := t.scr.GetContent(x+bx, ry)
				cst.bg = ri.style.bg
				t.scr.SetContent(x+bx, ry, ch, cst)
			}
		}
	}
}

func (t *TUI) footerText() string {
	var dirUsage, dirSize int64
	itemCount := 0
	for _, it := range t.rows {
		dirUsage += it.GetUsage()
		dirSize += it.GetSize()
		itemCount += it.GetItemCount()
	}
	selected := ""
	if len(t.markedRows) > 0 {
		var mu, ms int64
		for it := range t.markedRows {
			mu += it.GetUsage()
			ms += it.GetSize()
		}
		_ = ms
		selected = fmt.Sprintf(" Selected items: [::b]%d[::-]", len(t.markedRows))
	}
	return fmt.Sprintf("%s Total disk usage: [::b]%s[::-] Apparent size: [::b]%s[::-] Items: [::b]%d[::-] Sorting by: %s %s",
		selected, t.footerSize(dirUsage), t.footerSize(dirSize), itemCount, t.sortBy, t.sortOrder)
}

func (t *TUI) footerSize(size int64) string {
	n, u := formatSizeParts(size, t.useSI)
	return n + "[::-] " + u + "[::b]"
}

// drawFooterText draws footer with styled numbers
func (t *TUI) drawFooter(x, y, width int) {
	text := t.footerText()
	// convert [::b] / [::-] into number style switches
	var runes []styledRune
	parts := splitKeep(text)
	cur := t.footerStyle
	for _, p := range parts {
		switch p {
		case "[::b]":
			cur = t.footerNum
			continue
		case "[::-]":
			cur = t.footerStyle
			continue
		}
		for _, r := range p {
			runes = append(runes, styledRune{r, runeWidth(r), cur})
		}
	}
	lines := wordWrapRunes(runes, width)
	if len(lines) > 0 {
		printRunes(t.scr, lines[0], x, y, width, AlignLeft, false)
	}
}

func splitKeep(s string) []string {
	var res []string
	for len(s) > 0 {
		i1 := strings.Index(s, "[::b]")
		i2 := strings.Index(s, "[::-]")
		i := i1
		if i < 0 || (i2 >= 0 && i2 < i) {
			i = i2
		}
		if i < 0 {
			res = append(res, s)
			break
		}
		if i > 0 {
			res = append(res, s[:i])
		}
		res = append(res, s[i:i+5])
		s = s[i+5:]
	}
	return res
}

func (t *TUI) draw() {
	t.scr.Clear()
	w, h := t.scr.Size()
	y := 0
	if !t.headerHidden {
		printRunes(t.scr, parseTagged(" gdu ~ Use arrow keys to navigate, press ? for help ", t.headerStyle), 0, 0, w, AlignLeft, false)
		y = 1
	}
	if t.showDevices && t.currentDir == nil {
		t.drawDevices(y)
	} else if t.currentDir != nil {
		label := "[::b] --- " + tviewEscape(t.dirPath(t.currentDir)) + " ---"
		printTagged(t.scr, label, 0, y, w, AlignLeft, StyleDefault, false)
		t.drawTable()
		fx := 0
		if t.filterShown {
			fx = t.drawFilterInput(h - 1)
		}
		t.drawFooter(fx, h-1, w-fx)
	} else {
		printTagged(t.scr, " No items to display.", 0, h-1, w, AlignLeft, StyleDefault, false)
	}
	for _, m := range t.modals {
		m.Draw(t)
	}
	t.scr.Show()
}

// ---------- filter input ----------

func (t *TUI) drawFilterInput(y int) int {
	width := 15
	w, _ := t.scr.Size()
	if width > w {
		width = w
	}
	fieldStyle := StyleDefault.Fg(ColorWhite).Bg(ColorBlue)
	if !t.useColors {
		fieldStyle = StyleDefault.Fg(ColorBlack).Bg(ColorWhite)
	}
	for x := 0; x < width; x++ {
		t.scr.SetContent(x, y, ' ', fieldStyle)
	}
	text := t.filterValue
	runes := []rune(text)
	vis := runes
	tw := stringWidth(text)
	if tw >= width {
		// show the end of the text
		for stringWidth(string(vis)) >= width && len(vis) > 0 {
			vis = vis[1:]
		}
	}
	px := 0
	for _, r := range vis {
		rw := runeWidth(r)
		if rw == 2 {
			t.scr.SetWide(px, y, r, 2, fieldStyle)
		} else {
			t.scr.SetContent(px, y, r, fieldStyle)
		}
		px += rw
	}
	if t.filtering {
		t.scr.showCursor = true
		t.scr.cursorX = px
		t.scr.cursorY = y
	}
	return width + 1
}

// ---------- events ----------

func (t *TUI) handleEvent(ev Event) {
	if ev.Key == KeyResize {
		w, h := termSize(t.term.out.Fd())
		t.scr.Resize(w, h)
		return
	}
	if len(t.modals) > 0 {
		m := t.modals[len(t.modals)-1]
		m.HandleEvent(t, ev)
		return
	}
	if t.filtering {
		t.handleFilterKey(ev)
		return
	}
	if t.showDevices && t.currentDir == nil {
		t.handleDevicesKey(ev)
		return
	}
	t.handleMainKey(ev)
}

func (t *TUI) pushModal(m modal) { t.modals = append(t.modals, m) }
func (t *TUI) popModal() {
	if len(t.modals) > 0 {
		t.modals = t.modals[:len(t.modals)-1]
	}
}

func (t *TUI) handleFilterKey(ev Event) {
	switch ev.Key {
	case KeyEsc:
		t.filterValue = ""
		t.filtering = false
		t.filterShown = false
		t.scr.showCursor = false
		t.showDir(nil)
	case KeyEnter, KeyTab:
		t.filtering = false
		t.scr.showCursor = false
	case KeyBackspace:
		r := []rune(t.filterValue)
		if len(r) > 0 {
			t.filterValue = string(r[:len(r)-1])
			t.showDir(nil)
		}
	case KeyRune:
		t.filterValue += string(ev.Rune)
		t.showDir(nil)
	}
}

func (t *TUI) visibleHeight() int {
	_, _, _, h := t.tableRect()
	return h
}

func (t *TUI) handleMainKey(ev Event) {
	switch ev.Key {
	case KeyCtrl:
		if ev.Rune == 'c' {
			t.quit = true
		}
		return
	case KeyUp:
		t.moveSelection(-1)
		return
	case KeyDown:
		t.moveSelection(1)
		return
	case KeyHome:
		t.selected = 0
		return
	case KeyEnd:
		t.selected = t.rowCount() - 1
		return
	case KeyPgDn:
		t.pageMove(1)
		return
	case KeyPgUp:
		t.pageMove(-1)
		return
	case KeyEnter, KeyRight:
		t.enterSelected()
		return
	case KeyLeft:
		t.goBack()
		return
	case KeyEsc:
		if t.filterValue != "" || t.filterShown {
			t.filterValue = ""
			t.filterShown = false
			t.showDir(t.selectedItem())
		}
		return
	case KeyRune:
	default:
		return
	}
	switch ev.Rune {
	case 'q':
		t.quit = true
	case 'Q':
		t.quit = true
		t.printCwd = true
	case 'j':
		t.moveSelection(1)
	case 'k':
		t.moveSelection(-1)
	case 'g':
		t.selected = 0
	case 'G':
		t.selected = t.rowCount() - 1
	case 'l':
		t.enterSelected()
	case 'h':
		t.goBack()
	case '?':
		t.pushModal(newHelpModal())
	case 'i':
		if it := t.selectedItem(); it != nil {
			t.pushModal(newInfoModal(t, it))
		}
	case 'a':
		t.showApparentSize = !t.showApparentSize
		t.refreshKeepSelection()
	case 'B':
		t.showRelativeSize = !t.showRelativeSize
	case 'c':
		t.showItemCount = !t.showItemCount
	case 'm':
		t.showMtime = !t.showMtime
	case 'n':
		t.setSorting("name")
	case 's':
		t.setSorting("size")
	case 'C':
		t.setSorting("itemCount")
	case 'M':
		t.setSorting("mtime")
	case '/':
		t.filtering = true
		t.filterShown = true
	case ' ':
		t.toggleMark()
	case 'd':
		t.askDelete(false)
	case 'e':
		t.askDelete(true)
	case 'r':
		t.rescan()
	case 'b':
		t.spawnShell()
	case 'v':
		t.viewFile()
	case 'I':
		t.ignoreItem()
	case 'E':
		t.askExport()
	}
}

func (t *TUI) moveSelection(d int) {
	n := t.rowCount()
	t.selected += d
	if t.selected >= n {
		t.selected = n - 1
	}
	if t.selected < 0 {
		t.selected = 0
	}
}

func (t *TUI) pageMove(dir int) {
	h := t.visibleHeight()
	n := t.rowCount()
	if dir > 0 {
		t.selected += h
		t.offset += h
		if t.selected >= n {
			t.selected = n - 1
		}
	} else {
		t.selected -= h
		t.offset -= h
		if t.selected < 0 {
			t.selected = 0
		}
	}
}

func (t *TUI) setSorting(by string) {
	if t.sortBy == by {
		if t.sortOrder == "asc" {
			t.sortOrder = "desc"
		} else {
			t.sortOrder = "asc"
		}
	} else {
		t.sortBy = by
		if by == "name" {
			t.sortOrder = "asc"
		} else {
			t.sortOrder = "asc"
		}
	}
	t.refreshKeepSelection()
}

func (t *TUI) refreshKeepSelection() {
	sel := t.selectedItem()
	t.showDir(sel)
}

func (t *TUI) enterSelected() {
	if t.currentDir == nil {
		return
	}
	if t.hasParent && t.selected == 0 {
		t.goBack()
		return
	}
	it := t.selectedItem()
	d, ok := it.(*Dir)
	if !ok {
		return
	}
	t.currentDir = d
	t.showDir(nil)
}

func (t *TUI) goBack() {
	if t.currentDir == nil || t.currentDir == t.topDir || t.currentDir.Parent == nil {
		return
	}
	prev := t.currentDir
	t.currentDir = prev.Parent
	t.showDir(prev)
}

func (t *TUI) toggleMark() {
	it := t.selectedItem()
	if it == nil {
		return
	}
	if t.markedRows[it] {
		delete(t.markedRows, it)
	} else {
		t.markedRows[it] = true
	}
	t.moveSelection(1)
}

// ---------- actions ----------

func (t *TUI) askDelete(empty bool) {
	if t.noDelete {
		t.pushModal(newMessageModal("Deletion is disabled!"))
		return
	}
	var items []Item
	if len(t.markedRows) > 0 {
		for _, it := range t.rows {
			if t.markedRows[it] {
				items = append(items, it)
			}
		}
	} else {
		it := t.selectedItem()
		if it == nil {
			return
		}
		items = []Item{it}
	}
	action := "delete"
	if empty {
		action = "empty"
	}
	var text string
	if len(items) == 1 {
		text = fmt.Sprintf("Are you sure you want to %s \"%s\"?", action, tviewEscape(items[0].GetName()))
	} else {
		text = fmt.Sprintf("Are you sure you want to %s %d items?", action, len(items))
	}
	if !t.askBeforeDelete {
		t.doDelete(items, empty)
		return
	}
	m := newConfirmModal(text, []string{"no", "yes", "don't ask me again"}, func(idx int) {
		t.popModal()
		switch idx {
		case 1:
			t.doDelete(items, empty)
		case 2:
			t.askBeforeDelete = false
			t.doDelete(items, empty)
		}
	})
	t.pushModal(m)
}

func (t *TUI) doDelete(items []Item, empty bool) {
	for _, it := range items {
		path := it.GetPath()
		if empty {
			if d, ok := it.(*Dir); ok {
				for _, f := range d.Files {
					os.RemoveAll(f.GetPath())
				}
				d.Files = nil
			} else {
				os.Truncate(path, 0)
				if f, ok := it.(*File); ok {
					f.Size = 0
					f.Usage = 0
				}
			}
		} else {
			if err := os.RemoveAll(path); err != nil {
				continue
			}
			if p := it.GetParent(); p != nil {
				p.RemoveFile(it)
			}
		}
		delete(t.markedRows, it)
	}
	t.markedRows = map[Item]bool{}
	t.recalcStats()
	sel := t.selected
	t.showDir(nil)
	t.selected = sel
}

func (t *TUI) recalcStats() {
	if t.topDir != nil {
		t.topDir.UpdateStats(map[uint64]bool{})
	}
}

func (t *TUI) rescan() {
	if t.currentDir == nil {
		return
	}
	path := t.currentDir.GetPath()
	parent := t.currentDir.Parent
	isTop := t.currentDir == t.topDir
	t.startScan(path, func(d *Dir) {
		if isTop || parent == nil {
			d.Name = path
			if t.topDir != nil {
				d.BasePath = ""
			}
			t.topDir = d
			t.currentDir = d
		} else {
			d.Name = filepath.Base(path)
			d.Parent = parent
			for i, f := range parent.Files {
				if f == Item(t.currentDir) {
					parent.Files[i] = d
				}
			}
			t.currentDir = d
			t.recalcStats()
		}
		t.showDir(nil)
	})
}

func (t *TUI) spawnShell() {
	if t.noSpawnShell {
		return
	}
	if t.currentDir == nil {
		return
	}
	shell := os.Getenv("SHELL")
	if shell == "" {
		shell = "/bin/sh"
	}
	t.term.Suspend()
	cmd := exec.Command(shell)
	cmd.Dir = t.currentDir.GetPath()
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	cmd.Run()
	t.term.Resume()
	t.scr.Invalidate()
}

func (t *TUI) viewFile() {
	it := t.selectedItem()
	if it == nil || it.IsDir() {
		return
	}
	t.pushModal(newFileViewer(t, it))
}

func (t *TUI) ignoreItem() {
	it := t.selectedItem()
	if it == nil {
		return
	}
	p := it.GetPath()
	if t.ignored[p] {
		delete(t.ignored, p)
	} else {
		t.ignored[p] = true
	}
	t.moveSelection(1)
}

func (t *TUI) askExport() {
	t.pushModal(newExportModal(t))
}

// ---------- scanning ----------

func (t *TUI) startScan(path string, done func(d *Dir)) {
	t.scanning = true
	t.scanStart = time.Now()
	pm := &progressModal{}
	t.pushModal(pm)
	go func() {
		stop := make(chan struct{})
		go func() {
			for {
				select {
				case <-stop:
					return
				case <-time.After(100 * time.Millisecond):
					t.requestRedraw()
				}
			}
		}()
		a := *t.analyzer
		a.itemCount = 0
		a.totalSize = 0
		d := a.AnalyzeDir(path)
		close(stop)
		t.post(func() {
			t.scanning = false
			for i, m := range t.modals {
				if m == modal(pm) {
					t.modals = append(t.modals[:i], t.modals[i+1:]...)
					break
				}
			}
			done(d)
		})
	}()
	t.progressAnalyzer = &a0{}
	_ = pm
}

type a0 struct{}

// ---------- main loop ----------

func (t *TUI) run() error {
	for !t.quit {
		t.draw()
		select {
		case ev := <-t.term.events:
			t.handleEvent(ev)
		case f := <-t.tasks:
			f()
		case <-t.redraw:
		}
		// drain
	drain:
		for {
			select {
			case f := <-t.tasks:
				f()
			default:
				break drain
			}
		}
	}
	return nil
}

func runTUI(cfg *Config, a *Analyzer, path string) error {
	t := newTUI(cfg, a)
	var dir *Dir
	var err error
	if showDisks {
		devs, err := getDevicesInfo()
		if err != nil {
			return fmt.Errorf("loading mount points: %w", err)
		}
		t.devices = devs
		t.showDevices = true
	} else if cfg.InputFile != "" {
		fh, e := os.Open(cfg.InputFile)
		if e != nil {
			return fmt.Errorf("opening input file: %w", e)
		}
		defer handleImportPanic()
		dir, err = ReadAnalysis(fh)
		fh.Close()
		if err != nil {
			return fmt.Errorf("reading analysis: %w", err)
		}
		dir.UpdateStats(map[uint64]bool{})
	} else {
		abs, e := absPath(path)
		if e != nil {
			return e
		}
		if _, e := os.Stat(abs); e != nil {
			return e
		}
		path = abs
	}
	term, err := openTerminal(cfg.Mouse)
	if err != nil {
		return err
	}
	t.term = term
	t.scr = newScreen(os.Stdout)
	w, h := termSize(os.Stdout.Fd())
	t.scr.Resize(w, h)
	if dir != nil {
		t.topDir = dir
		t.currentDir = dir
		t.showDir(nil)
	} else if !t.showDevices {
		t.startScan(path, func(d *Dir) {
			t.topDir = d
			t.currentDir = d
			t.showDir(nil)
		})
	}
	t.run()
	term.Close()
	if t.printCwd && t.currentDir != nil {
		fmt.Println(t.currentDir.GetPath())
	}
	return nil
}
