func parseTaggedStateful(line string, base Style, tv *textView) []styledRune {
	return parseTagged(line, base)
}

// parseTaggedLines parses a multi-line text keeping tag state across lines
func parseTaggedLines(text string, base Style) [][]styledRune {
	all := parseTagged(text, base)
	var lines [][]styledRune
	var cur []styledRune
	for _, r := range all {
		if r.r == '\n' {
			lines = append(lines, cur)
			cur = nil
			continue
		}
		cur = append(cur, r)
	}
	lines = append(lines, cur)
	return lines
}

func (tv *textView) draw(scr *Screen, x, y, w, h int) {
	ix, iy, iw, ih := x+tv.padL, y+tv.padT, w-tv.padL-tv.padR, h-tv.padT-tv.padB
	if iw <= 0 || ih <= 0 {
		return
	}
	maxScroll := len(tv.lines) - ih
	if maxScroll < 0 {
		maxScroll = 0
	}
	if tv.scroll > maxScroll {
		tv.scroll = maxScroll
	}
	if tv.scroll < 0 {
		tv.scroll = 0
	}
	for i := 0; i < ih && tv.scroll+i < len(tv.lines); i++ {
		printRunes(scr, tv.lines[tv.scroll+i], ix, iy+i, iw, AlignLeft, true)
	}
}

