// ---------- confirm (tview Modal) ----------

type confirmModal struct {
	text    string
	buttons []string
	focus   int
	done    func(int)
}

func newConfirmModal(text string, buttons []string, done func(int)) *confirmModal {
	return &confirmModal{text: text, buttons: buttons, done: done}
}

func (m *confirmModal) Draw(t *TUI) {
	sw, sh := t.scr.Size()
	buttonsWidth := 0
	for _, b := range m.buttons {
		buttonsWidth += taggedWidth(b) + 4 + 2
	}
	buttonsWidth -= 2
	width := sw / 3
	if width < buttonsWidth {
		width = buttonsWidth
	}
	var lines [][]styledRune
	textStyle := StyleDefault.Fg(ColorWhite).Bg(ColorBlack)
	for _, l := range strings.Split(m.text, "\n") {
		if l == "" {
			lines = append(lines, nil)
			continue
		}
		lines = append(lines, wordWrapWords(parseTagged(l, textStyle), width)...)
	}
	height := len(lines) + 6
	width += 4
	x := (sw - width) / 2
	y := (sh - height) / 2
	// outer box: border with blue background
	drawBox(t.scr, x, y, width, height, StyleDefault.Bg(ColorBlue), true, true, StyleDefault.Bg(ColorBlue), "", StyleDefault)
	// frame inside
	fx, fy, fw, fh := x+1, y+1, width-2, height-2
	for yy := fy; yy < fy+fh; yy++ {
		for xx := fx; xx < fx+fw; xx++ {
			t.scr.SetContent(xx, yy, ' ', modalBg)
		}
	}
	ix, iy, iw, ih := fx+1, fy+1, fw-2, fh-2
	top := iy
	bottom := iy + ih - 1
	for i, l := range lines {
		ly := iy + i
		if ly >= bottom {
			continue
		}
		printRunes(t.scr, l, ix, ly, iw, AlignCenter, true)
		if ly+1 > top {
			top = ly + 1
		}
	}
	top++ // header spacing
	if top > bottom {
		return
	}
	// buttons
	bw := make([]int, len(m.buttons))
	total := 0
	for i, b := range m.buttons {
		bw[i] = taggedWidth(b) + 4
		total += bw[i] + 1
	}
	total--
	bx := ix
	right := ix + iw
	if bx+total < right {
		bx = (bx + right - total) / 2
	}
	for i, b := range m.buttons {
		space := right - bx
		w := bw[i]
		if w > space {
			w = space
		}
		if w <= 0 {
			break
		}
		st := StyleDefault.Fg(ColorWhite).Bg(ColorBlack)
		lst := StyleDefault.Fg(ColorWhite).Bg(ColorBlack)
		if i == m.focus {
			st = StyleDefault.Bg(ColorWhite)
			lst = StyleDefault.Fg(ColorBlack).Bg(ColorWhite)
		}
		for xx := bx; xx < bx+w; xx++ {
			t.scr.SetContent(xx, top, ' ', StyleDefault.Bg(st.bg))
		}
		printRunes(t.scr, parseTagged(b, lst), bx, top, w, AlignCenter, true)
		bx += w + 1
	}
}

func (m *confirmModal) HandleEvent(t *TUI, ev Event) bool {
	switch ev.Key {
	case KeyEsc:
		m.done(-1)
	case KeyEnter:
		m.done(m.focus)
	case KeyTab, KeyRight, KeyDown:
		m.focus = (m.focus + 1) % len(m.buttons)
	case KeyBacktab, KeyLeft, KeyUp:
		m.focus = (m.focus - 1 + len(m.buttons)) % len(m.buttons)
	case KeyRune:
		switch ev.Rune {
		case ' ':
			m.done(m.focus)
		}
	}
	return true
}

// wordWrapWords wraps on word boundaries (tview WordWrap)
func wordWrapWords(runes []styledRune, width int) [][]styledRune {
	if width <= 0 {
		return [][]styledRune{runes}
	}
	var lines [][]styledRune
	for len(runes) > 0 {
		w := 0
		for _, r := range runes {
			w += r.w
		}
		if w <= width {
			lines = append(lines, trimRight(runes))
			break
		}
		// find break: last space within width
		cw := 0
		breakAt := -1
		cut := len(runes)
		for i, r := range runes {
			if cw+r.w > width {
				cut = i
				break
			}
			cw += r.w
			if r.r == ' ' {
				breakAt = i
			}
		}
		if cut < len(runes) && runes[cut].r == ' ' {
			breakAt = cut
		}
		if breakAt > 0 {
			lines = append(lines, trimRight(runes[:breakAt]))
			runes = runes[breakAt:]
			for len(runes) > 0 && runes[0].r == ' ' {
				runes = runes[1:]
			}
		} else {
			lines = append(lines, runes[:cut])
			runes = runes[cut:]
		}
	}
	return lines
}

func trimRight(r []styledRune) []styledRune {
	for len(r) > 0 && r[len(r)-1].r == ' ' {
		r = r[:len(r)-1]
	}
	return r
}

// ---------- simple message ----------

func newMessageModal(text string) *confirmModal {
	var m *confirmModal
	m = newConfirmModal(text, []string{"ok"}, nil)
	return m
}

// ---------- progress ----------

type progressModal struct{}

func shortenPath(path string, maxLen int) string {
	if len(path) <= maxLen {
		return path
	}
	parts := strings.SplitAfter(path, "/")
	res := ""
	curLen := len(parts[len(parts)-1])
	for _, part := range parts[:len(parts)-1] {
		curLen += len(part)
		if curLen > maxLen {
			res += ".../"
			break
		}
		res += part
	}
	res += parts[len(parts)-1]
	return res
}

func (m *progressModal) Draw(t *TUI) {
	sw, sh := t.scr.Size()
	// flex: (nil,0,1) (modal,0,50) (nil,0,1)
	s1 := sw * 1 / 52
	rest := sw - s1
	mw := rest * 50 / 51
	mh := 8
	y := (sh - mh) / 2
	x := s1
	drawBox(t.scr, x, y, mw, mh, modalBg, true, false, modalBg, " Scanning... ", StyleDefault.Fg(titleColor).Bg(ColorBlack))
	p := t.analyzer.GetProgress()
	if t.curAnalyzer != nil {
		p = t.curAnalyzer.GetProgress()
	}
	el := time.Since(t.scanStart).Round(time.Second)
	maxLen := t.cfg.Style.ProgressPathMaxLen
	if maxLen <= 0 {
		maxLen = mw - 20
	}
	text := fmt.Sprintf("Total items: [red::b]%s[white:black:-], size: [red::b]%s[white:black:-] %s, elapsed time: [red::b]%s[white:black:-]\nCurrent item: [white::b]%s",
		formatNumber(p.ItemCount), sizeNum(p.TotalSize, t.useSI), sizeUnit(p.TotalSize, t.useSI), el.String(), tviewEscape(shortenPath(p.CurrentPath, maxLen)))
	tv := textView{padT: 2, padB: 2, padL: 2, padR: 2}
	tv.lines = parseTaggedLines(text, StyleDefault.Fg(ColorWhite).Bg(ColorBlack))
	tv.draw(t.scr, x+1, y+1, mw-2, mh-2)
}

func sizeNum(s int64, si bool) string  { n, _ := formatSizeParts(s, si); return n }
func sizeUnit(s int64, si bool) string { _, u := formatSizeParts(s, si); return u }

func (m *progressModal) HandleEvent(t *TUI, ev Event) bool {
	if ev.Key == KeyRune && ev.Rune == 'q' || ev.Key == KeyCtrl && ev.Rune == 'c' {
		t.quit = true
	}
	return true
}

// ---------- file viewer ----------

type fileViewer struct {
	tv    textView
	title string
}

func newFileViewer(t *TUI, it Item) *fileViewer {
	m := &fileViewer{title: " " + tviewEscape(it.GetPath()) + " "}
	f, err := os.Open(it.GetPath())
	if err == nil {
		defer f.Close()
		sc := bufio.NewScanner(f)
		sc.Buffer(make([]byte, 1024*1024), 1024*1024)
		n := 0
		for sc.Scan() && n < 1000 {
			m.tv.lines = append(m.tv.lines, parseTagged(tviewEscape(sc.Text()), StyleDefault))
			n++
		}
	}
	return m
}

func (m *fileViewer) Draw(t *TUI) {
	sw, sh := t.scr.Size()
	drawBox(t.scr, 0, 0, sw, sh, StyleDefault, true, true, StyleDefault, m.title, StyleDefault)
	m.tv.draw(t.scr, 1, 1, sw-2, sh-2)
}

func (m *fileViewer) HandleEvent(t *TUI, ev Event) bool {
	_, sh := t.scr.Size()
	switch ev.Key {
	case KeyEsc:
		t.popModal()
	case KeyUp:
		m.tv.scroll--
	case KeyDown:
		m.tv.scroll++
	case KeyPgDn:
		m.tv.scroll += sh - 2
	case KeyPgUp:
		m.tv.scroll -= sh - 2
	case KeyRune:
		switch ev.Rune {
		case 'q':
			t.popModal()
		case 'j':
			m.tv.scroll++
		case 'k':
			m.tv.scroll--
		case 'g':
			m.tv.scroll = 0
		case 'G':
			m.tv.scroll = len(m.tv.lines)
		}
	}
	if m.tv.scroll < 0 {
		m.tv.scroll = 0
	}
	return true
}

// ---------- export ----------

type exportModal struct {
	value string
}

func newExportModal(t *TUI) *exportModal { return &exportModal{value: "export.json"} }

func (m *exportModal) Draw(t *TUI) {
	sw, sh := t.scr.Size()
	w, h := 50, 7
	x, y := (sw-w)/2, (sh-h)/2
	drawBox(t.scr, x, y, w, h, modalBg, true, true, modalBg, " Export to file ", StyleDefault.Fg(titleColor).Bg(ColorBlack))
	printTagged(t.scr, "File name: ", x+2, y+3, w-4, AlignLeft, StyleDefault.Fg(ColorYellow).Bg(ColorBlack), false)
	fx := x + 2 + 11
	fw := w - 4 - 11
	for xx := fx; xx < fx+fw; xx++ {
		t.scr.SetContent(xx, y+3, ' ', StyleDefault.Fg(ColorWhite).Bg(ColorBlue))
	}
	printTagged(t.scr, tviewEscape(m.value), fx, y+3, fw, AlignLeft, StyleDefault.Fg(ColorWhite).Bg(ColorBlue), false)
}

func (m *exportModal) HandleEvent(t *TUI, ev Event) bool {
	switch ev.Key {
	case KeyEsc:
		t.popModal()
	case KeyEnter:
		t.popModal()
		if t.topDir != nil {
			if f, err := os.Create(m.value); err == nil {
				WriteAnalysis(f, t.topDir)
				f.Close()
			}
		}
	case KeyBackspace:
		r := []rune(m.value)
		if len(r) > 0 {
			m.value = string(r[:len(r)-1])
		}
	case KeyRune:
		m.value += string(ev.Rune)
	}
	return true
}
