}

func itemType(it Item) string {
	if it.IsDir() {
		return "Directory"
	}
	if it.GetFlag() == '@' {
		return "Other"
	}
	return "File"
}

func newInfoModal(t *TUI, it Item) *infoModal {
	m := &infoModal{}
	m.setItem(t, it)
	return m
}

func (m *infoModal) setItem(t *TUI, it Item) {
	m.item = it
	var sb strings.Builder
	num := t.numTag()
	if !t.useColors {
		num = "[::b]"
	}
	fs := func(size int64) string {
		n, u := formatSizeParts(size, t.useSI)
		return num + n + "[-::] " + u
	}
	sb.WriteString("[::b]Name:[::-] " + tviewEscape(it.GetName()) + "\\n")
	sb.WriteString("[::b]Path:[::-] " + tviewEscape(it.GetPath()) + "\\n")
	sb.WriteString("[::b]Type:[::-] " + itemType(it) + "\\n\\n")
	sb.WriteString("   [::b]Disk usage:[::-] " + fs(it.GetUsage()) + " (" + num + fmt.Sprintf("%d", it.GetUsage()) + "[-::] B)\\n")
	sb.WriteString("[::b]Apparent size:[::-] " + fs(it.GetSize()) + " (" + num + fmt.Sprintf("%d", it.GetSize()) + "[-::] B)")
	if it.IsHardLinked() && !it.IsDir() {
		sb.WriteString("\\n\\n[::b]Hard-linked files:\\n")
		var paths []string
		ino := it.GetMultiLinkedInode()
		for _, f := range HardLinks[ino] {
			paths = append(paths, f.GetPath())
		}
		for i, p := range paths {
			sb.WriteString("    " + tviewEscape(p))
			if i < len(paths)-1 {
				sb.WriteString("\\n")
			}
		}
	}
	m.tv.lines = parseTaggedLines(sb.String(), StyleDefault.Fg(ColorWhite).Bg(ColorBlack))
	m.tv.padT, m.tv.padB, m.tv.padL, m.tv.padR = 2, 2, 2, 2
}

func (m *infoModal) rect(t *TUI) (int, int, int, int) {
	w, h := t.scr.Size()
	mw := 80
	mh := len(m.tv.lines) + 6
	if mh > h {
		mh = h
	}
	return (w - mw) / 2, (h - mh) / 2, mw, mh
}

func (m *infoModal) Draw(t *TUI) {
	if it := t.selectedItem(); it != nil && it != m.item {
		m.setItem(t, it)
	}
	x, y, w, h := m.rect(t)
	drawBox(t.scr, x, y, w, h, modalBg, true, false, modalBg, " Item info ", StyleDefault.Fg(titleColor).Bg(ColorBlack))
	m.tv.draw(t.scr, x+1, y+1, w-2, h-2)
}

func (m *infoModal) HandleEvent(t *TUI, ev Event) bool {
	switch ev.Key {
	case KeyEsc:
		t.popModal()
		return true
	case KeyUp, KeyDown, KeyHome, KeyEnd, KeyPgUp, KeyPgDn:
		t.handleMainKey(ev)
		return true
	case KeyCtrl:
		if ev.Rune == 'c' {
			t.quit = true
		}
		return true
	case KeyRune:
		switch ev.Rune {
		case 'q', 'i':
			t.popModal()
		case 'j', 'k', 'g', 'G', 'a', 'B', 'c', 'm':
			t.handleMainKey(ev)
		}
	}
	return true
}

