type fileViewer struct {
	path   string
	lines  [][]styledRune // raw lines
	scroll int
	width  int
	wrapped [][]styledRune
}

func newFileViewer(t *TUI, it Item) *fileViewer {
	m := &fileViewer{path: it.GetPath()}
	f, err := os.Open(it.GetPath())
	if err != nil {
		return m
	}
	defer f.Close()
	rd := bufio.NewReader(f)
	var content []string
	for i := 0; i <= 500; i++ {
		line, isPrefix, err := rd.ReadLine()
		if err != nil {
			break
		}
		content = append(content, string(line))
		if isPrefix {
			break
		}
	}
	text := strings.Join(content, "\\n") + "\\n"
	first := true
	for _, l := range strings.Split(text, "\\n") {
		l = strings.ReplaceAll(l, "\\t", "    ")
		st := StyleDefault.Fg(ColorWhite)
		if first {
			st = st.Bg(ColorBlack)
			first = false
		}
		var runes []styledRune
		for _, r := range l {
			w := runeWidth(r)
			if w == 0 {
				continue
			}
			runes = append(runes, styledRune{r, w, st})
		}
		m.lines = append(m.lines, runes)
	}
	return m
}

func (m *fileViewer) layout(width int) {
	if m.width == width && m.wrapped != nil {
		return
	}
	m.width = width
	m.wrapped = nil
	for _, l := range m.lines {
		if len(l) == 0 {
			m.wrapped = append(m.wrapped, nil)
			continue
		}
		m.wrapped = append(m.wrapped, wordWrapRunes(l, width)...)
	}
}

func (m *fileViewer) draw(t *TUI, x, y, w, h int) {
	m.layout(w)
	maxScroll := len(m.wrapped) - h
	if maxScroll < 0 {
		maxScroll = 0
	}
	if m.scroll > maxScroll {
		m.scroll = maxScroll
	}
	if m.scroll < 0 {
		m.scroll = 0
	}
	for i := 0; i < h && m.scroll+i < len(m.wrapped); i++ {
		printRunes(t.scr, m.wrapped[m.scroll+i], x, y+i, w, AlignLeft, false)
	}
}

func (m *fileViewer) handle(t *TUI, ev Event) {
	_, _, _, h := t.tableRect()
	switch ev.Key {
	case KeyEsc:
		t.viewer = nil
	case KeyUp:
		m.scroll--
	case KeyDown:
		m.scroll++
	case KeyHome:
		m.scroll = 0
	case KeyEnd:
		m.scroll = 1 << 30
	case KeyPgDn:
		m.scroll += h
	case KeyPgUp:
		m.scroll -= h
	case KeyCtrl:
		if ev.Rune == 'c' {
			t.quit = true
		}
	case KeyRune:
		switch ev.Rune {
		case 'q':
			t.viewer = nil
		case 'j':
			m.scroll++
		case 'k':
			m.scroll--
		case 'g':
			m.scroll = 0
		case 'G':
			m.scroll = 1 << 30
		}
	}
	if m.scroll < 0 {
		m.scroll = 0
	}
	if m.wrapped != nil {
		mx := len(m.wrapped) - h
		if mx < 0 {
			mx = 0
		}
		if m.scroll > mx {
			m.scroll = mx
		}
	}
}

