package main

import (
	"embed"
	"fmt"
	"os"
	"strings"
)

//go:embed assets/*.txt
var assetsFS embed.FS

func asset(name string) string {
	b, _ := assetsFS.ReadFile("assets/" + name)
	return string(b)
}

var completionShells = []struct{ name, short string }{
	{"bash", "Generate the autocompletion script for bash"},
	{"fish", "Generate the autocompletion script for fish"},
	{"powershell", "Generate the autocompletion script for powershell"},
	{"zsh", "Generate the autocompletion script for zsh"},
}

func runCompletion(args []string) int {
	// find subcommand
	var shell string
	var rest []string
	for i, a := range args {
		if !strings.HasPrefix(a, "-") || a == "-" {
			for _, s := range completionShells {
				if s.name == a {
					shell = a
					rest = append(append([]string{}, args[:i]...), args[i+1:]...)
				}
			}
			break
		}
	}
	if shell == "" {
		// parse flags of completion command (only help)
		help := false
		fs := newFlagSet()
		fs.BoolVarP(&help, "help", "h", false, "help for completion")
		if err := fs.Parse(args); err != nil {
			fail(err)
		}
		fmt.Print(asset("help_completion.txt"))
		return 0
	}
	help := false
	noDesc := false
	fs := newFlagSet()
	fs.BoolVarP(&help, "help", "h", false, "help for "+shell)
	fs.BoolVarP(&noDesc, "no-descriptions", "", false, "disable completion descriptions")
	if err := fs.Parse(rest); err != nil {
		fail(err)
	}
	if help {
		fmt.Print(asset("help_completion_" + shell + ".txt"))
		return 0
	}
	if len(fs.args) > 0 {
		fail(fmt.Errorf("unknown command %q for %q", fs.args[0], "gdu completion "+shell))
	}
	script := asset("completion_" + shell + ".txt")
	if noDesc {
		script = strings.ReplaceAll(script, "__complete ", "__completeNoDesc ")
	}
	fmt.Print(script)
	return 0
}

func runComplete(args []string, withDesc bool) int {
	directive := 0
	var completions []string
	if len(args) == 0 {
		args = []string{""}
	}
	toComplete := args[len(args)-1]
	prev := args[:len(args)-1]

	emit := func() int {
		for _, c := range completions {
			if !withDesc {
				if i := strings.Index(c, "\t"); i >= 0 {
					c = c[:i]
				}
			}
			fmt.Println(c)
		}
		fmt.Printf(":%d\n", directive)
		name := "ShellCompDirectiveDefault"
		if directive == 4 {
			name = "ShellCompDirectiveNoFileComp"
		}
		fmt.Fprintf(os.Stderr, "Completion ended with directive: %s\n", name)
		return 0
	}

	// completion subcommand
	if len(prev) > 0 && prev[0] == "completion" {
		sub := prev[1:]
		var shell string
		for _, a := range sub {
			if !strings.HasPrefix(a, "-") {
				shell = a
				break
			}
		}
		if shell == "" {
			if strings.HasPrefix(toComplete, "-") {
				completions = append(completions, flagCompletions([]*Flag{{Name: "help", Shorthand: "h", Usage: "help for completion"}}, toComplete)...)
			} else {
				for _, s := range completionShells {
					if strings.HasPrefix(s.name, toComplete) {
						completions = append(completions, s.name+"\t"+s.short)
					}
				}
			}
			directive = 4
			return emit()
		}
		if strings.HasPrefix(toComplete, "-") {
			completions = append(completions, flagCompletions([]*Flag{
				{Name: "help", Shorthand: "h", Usage: "help for " + shell},
				{Name: "no-descriptions", Usage: "disable completion descriptions"},
			}, toComplete)...)
		}
		directive = 4
		return emit()
	}

	var f Flags
	fs := newFlagSet()
	fs = defineFlags(&f)
	used := map[string]bool{}
	afterDashes := false
	needValue := false
	for i := 0; i < len(prev); i++ {
		a := prev[i]
		if afterDashes {
			continue
		}
		if a == "--" {
			afterDashes = true
			continue
		}
		if strings.HasPrefix(a, "--") {
			name := strings.SplitN(a[2:], "=", 2)[0]
			if fl, ok := fs.byName[name]; ok {
				used[fl.Name] = true
				if fl.Kind != kindBool && !strings.Contains(a, "=") {
					if i == len(prev)-1 {
						needValue = true
					}
					i++
				}
			}
			continue
		}
		if strings.HasPrefix(a, "-") && len(a) > 1 {
			sh := a[1:]
			for j := 0; j < len(sh); j++ {
				fl, ok := fs.byShort[sh[j:j+1]]
				if !ok {
					break
				}
				used[fl.Name] = true
				if fl.Kind != kindBool {
					if j == len(sh)-1 {
						if i == len(prev)-1 {
							needValue = true
						}
						i++
					}
					break
				}
			}
		}
	}
	if needValue || afterDashes {
		return emit()
	}
	if strings.HasPrefix(toComplete, "-") {
		if strings.Contains(toComplete, "=") {
			return emit()
		}
		var list []*Flag
		for _, fl := range fs.sortedFlags() {
			if used[fl.Name] && fl.Kind != kindStringSlice {
				continue
			}
			list = append(list, fl)
		}
		completions = flagCompletions(list, toComplete)
		directive = 4
		return emit()
	}
	return emit()
}

func flagCompletions(flags []*Flag, toComplete string) []string {
	var res []string
	for _, fl := range flags {
		name := "--" + fl.Name
		if strings.HasPrefix(name, toComplete) {
			res = append(res, name+"\t"+fl.Usage)
		}
		if fl.Shorthand != "" && strings.HasPrefix("-"+fl.Shorthand, toComplete) {
			res = append(res, "-"+fl.Shorthand+"\t"+fl.Usage)
		}
	}
	return res
}
