package main

import (
	"fmt"
	"sort"
)

func (t *TUI) sortDevices() {
	less := func(i, j int) bool { return t.devices[i].Size < t.devices[j].Size }
	if t.devSortBy == "name" {
		less = func(i, j int) bool { return naturalLess(t.devices[i].Name, t.devices[j].Name) }
	}
	if t.devSortOrder == "desc" {
		sort.SliceStable(t.devices, func(i, j int) bool { return less(j, i) })
	} else {
		sort.SliceStable(t.devices, less)
	}
}

func deviceUsagePart(d *Device, noUnicode bool) string {
	part := 0
	if d.Size > 0 {
		part = int(float64(d.Size-d.Free) / float64(d.Size) * 100.0)
	}
	return " " + usageGraph(part, noUnicode)
}

func (t *TUI) drawDevices(y int) {
	w, h := t.scr.Size()
	if t.devLabel != "" {
		printTagged(t.scr, "[::b] --- "+tviewEscape(t.devLabel)+" ---", 0, y, w, AlignLeft, StyleDefault, false)
	}
	textColor := "[" + t.dirColor + ":-:b]"
	sizeColor := "[#edb20a:-:b]"
	if !t.useColors {
		textColor = "[white:-:b]"
		sizeColor = "[white:-:b]"
	}
	cells := [][]string{{"Device name", "Size", "Used", "Used part", "Free", "Mount point"}}
	for _, d := range t.devices {
		cells = append(cells, []string{
