}

// canBreakBetween reports a line break opportunity between a and b (simplified UAX #14)
func canBreakBetween(a, b rune) bool {
	if b == ' ' {
		return false
	}
	if a == ' ' {
		return true
	}
	if a == '/' && !(b >= '0' && b <= '9') {
		return true
	}
	if a == '-' && unicode.IsLetter(b) {
		return true
	}
	if isCJK(a) || isCJK(b) {
		if strings.ContainsRune("、。，．：；？！）」』】〉》", b) {
			return false
		}
		return true
	}
	return false
}

// wordWrapRunes splits styled runes into lines of at most width, breaking at opportunities
func wordWrapRunes(runes []styledRune, width int) [][]styledRune {
	var lines [][]styledRune
	if width <= 0 {
		return [][]styledRune{runes}
	}
	for len(runes) > 0 {
		w := 0
		cut := -1
		lastBreak := -1
		for i, r := range runes {
			if w+r.w > width {
				// trailing spaces may overflow
				if r.r == ' ' {
					w += r.w
					continue
				}
				cut = i
				break
			}
			w += r.w
			if i+1 < len(runes) && canBreakBetween(r.r, runes[i+1].r) {
				lastBreak = i + 1
			}
		}
		if cut < 0 {
			lines = append(lines, runes)
			break
		}
		if lastBreak > 0 {
			cut = lastBreak
		}
		if cut == 0 {
			cut = 1
