// wordWrapRunes splits styled runes into lines of at most width, breaking at opportunities
func wordWrapRunes(runes []styledRune, width int) [][]styledRune {
	var lines [][]styledRune
	if width <= 0 {
		return [][]styledRune{runes}
	}
