{"command":"cd /workspace && cat > archive.go <<'EOF'
package main

import (
	"archive/zip"
	"path/filepath"
	"strings"
	"time"
)

func isArchive(name string) bool {
	ext := strings.ToLower(filepath.Ext(name))
	return ext == ".zip" || ext == ".jar"
}

// processArchive builds a directory tree from a zip archive
func processArchive(path, name string, mtime time.Time, parent *Dir) *Dir {
	r, err := zip.OpenReader(path)
	if err != nil {
		return nil
	}
	defer r.Close()
	root := &Dir{File: File{Name: name, Flag: 'Z', Mtime: mtime, Mtimeok: true, Parent: parent}, ItemCount: 1}
	dirs := map[string]*Dir{"": root}
	var getDir func(p string) *Dir
	getDir = func(p string) *Dir {
		p = strings.Trim(p, "/")
		if d, ok := dirs[p]; ok {
			return d
		}
		parentPath := ""
		base := p
		if i := strings.LastIndex(p, "/"); i >= 0 {
			parentPath = p[:i]
			base = p[i+1:]
		}
		pd := getDir(parentPath)
		d := &Dir{File: File{Name: base, Flag: 'Z', Mtime: mtime, Mtimeok: true, Parent: pd}, ItemCount: 1}
		pd.Files = append(pd.Files, d)
		dirs[p] = d
		return d
	}
	for _, f := range r.File {
		n := f.Name
		if strings.HasSuffix(n, "/") {
			getDir(n)
			continue
		}
		dirPath := ""
		base := n
		if i := strings.LastIndex(n, "/"); i >= 0 {
			dirPath = n[:i]
			base = n[i+1:]
		}
		d := getDir(dirPath)
		file := &File{
			Name:    base,
			Flag:    ' ',
			Size:    int64(f.UncompressedSize64),
			Usage:   int64(f.CompressedSize64),
			Mtime:   f.Modified,
			Mtimeok: true,
			Parent:  d,
		}
		d.Files = append(d.Files, file)
	}
	return root
}
